{
  "code": "import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/headless-publishing-platform.db"
);

export interface Post {
  id: number;
  title: string;
  content: string;
  status: "published" | "draft";
  created_at: string;
  updated_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS posts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('published', 'draft')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllPosts(): Post[] {
  const stmt = db.prepare(`SELECT * FROM posts ORDER BY created_at DESC`);
  return stmt.all() as unknown as Post[];
}

export function getPostById(id: number): Post | undefined {
  const stmt = db.prepare(
    `SELECT * FROM posts WHERE id = ? LIMIT 1`
  );
  return stmt.get(id) as unknown as Post | undefined;
}

export function insertPost(post: Omit<Post, "id" | "created_at" | "updated_at">): number {
  const stmt = db.prepare(
    `INSERT INTO posts (title, content, status, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(
    post.title,
    post.content,
    post.status,
    new Date().toISOString(),
    new Date().toISOString()
  );
  return Number(result.lastInsertRowid);
}

export function updatePost(
  id: number,
  post: Partial<Omit<Post, "id" | "created_at">>
): boolean {
  const updates = Object.keys(post)
    .filter(key => key !== "id" && key !== "created_at")
    .map(key => `${key} = ?`)
    .join(", ");

  if (!updates) return false;

  const stmt = db.prepare(
    `UPDATE posts SET ${updates}, updated_at = ? WHERE id = ?`
  );

  const values = [...Object.values(post), new Date().toISOString(), id];
  const result = stmt.run(...values);
  return result.changes > 0;
}

export function deletePost(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM posts WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllPosts().length === 0) {
  const samplePosts = [
    {
      title: "Getting Started with Headless CMS",
      content: "A comprehensive guide to setting up your first headless publishing platform...",
      status: "published" as const
    },
    {
      title: "Understanding Content Models",
      content: "Learn how to design flexible content models for your publishing workflow...",
      status: "draft" as const
    },
    {
      title: "Optimizing for Performance",
      content: "Tips and tricks for making your headless platform fast and scalable...",
      status: "published" as const
    }
  ];

  samplePosts.forEach(post => {
    insertPost({
      ...post,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    });
  });
}"
}

