{
    "code": "import { Router, type Request, type Response } from "express";
import {
  getAllPosts,
  getPostById,
  insertPost,
  updatePost,
  deletePost
} from "../db/posts-table";

export const router = Router();

// Get all posts
router.get("/", (req: Request, res: Response) => {
  try {
    const posts = getAllPosts();
    res.json(posts);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch posts" });
  }
});

// Get a single post by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid post ID" });
    }

    const post = getPostById(id);
    if (!post) {
      return res.status(404).json({ error: "Post not found" });
    }

    res.json(post);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch post" });
  }
});

// Create a new post
router.post("/", (req: Request, res: Response) => {
  try {
    const { title, content, status } = req.body;

    if (!title || !content || !status) {
      return res.status(400).json({ error: "Title, content, and status are required" });
    }

    const newPostId = insertPost({
      title,
      content,
      status
    });

    const createdPost = getPostById(newPostId);
    if (!createdPost) {
      return res.status(500).json({ error: "Failed to create post" });
    }

    res.status(201).json(createdPost);
  } catch (error) {
    res.status(500).json({ error: "Failed to create post" });
  }
});

// Update a post
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid post ID" });
    }

    const { title, content, status } = req.body;

    const postExists = getPostById(id);
    if (!postExists) {
      return res.status(404).json({ error: "Post not found" });
    }

    const updated = updatePost(id, { title, content, status });

    if (!updated) {
      return res.status(500).json({ error: "Failed to update post" });
    }

    const updatedPost = getPostById(id);
    if (!updatedPost) {
      return res.status(500).json({ error: "Failed to retrieve updated post" });
    }

    res.json(updatedPost);
  } catch (error) {
    res.status(500).json({ error: "Failed to update post" });
  }
});

// Delete a post
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid post ID" });
    }

    const postExists = getPostById(id);
    if (!postExists) {
      return res.status(404).json({ error: "Post not found" });
    }

    const deleted = deletePost(id);

    if (!deleted) {
      return res.status(500).json({ error: "Failed to delete post" });
    }

    res.json({ message: "Post deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete post" });
  }
});"
}

