interface ContentItem {
  id: string;
  title: string;
  content: string;
  published: boolean;
}

export function SiteThemeRenderer() {
  const [contentItems, setContentItems] = useState<ContentItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchContent();
  }, []);

  const fetchContent = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/headless-cms-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const items = await response.json();
      setContentItems(items);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (contentItems.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No content available.</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    }}>
      <h1 style={{ textAlign: 'center' }}>Published Content</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {contentItems.map((item) => (
          <div 
            key={item.id}
            style={{
              border: '1px solid #ddd',
              borderRadius: '8px',
              padding: '15px',
              backgroundColor: '#f9f9f9',
            }}
          >
            <h2 style={{ margin: '0 0 10px 0', color: '#333' }}>{item.title}</h2>
            <p style={{ margin: '0 0 10px 0', color: '#555' }}>{item.content}</p>
            <p style={{ margin: '0', color: item.published ? '#006400' : '#888' }}>
              {item.published ? 'Published' : 'Draft'}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}"
}

