  const stmt = db.prepare(`SELECT * FROM notes WHERE id = ?`);
  return stmt.get(id) as unknown as Note | undefined;
}

export function insertNote(content: string, timestamp: number, visible: boolean): number {
  const stmt = db.prepare(
    `INSERT INTO notes (content, timestamp, visible) VALUES (?, ?, ?)`
  );
  const result = stmt.run(content, timestamp, visible);
  return Number(result.lastInsertRowid);
}

