  "code": "import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

function getEnvVar(name: string): string {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Environment variable ${name} is not set`);
  }
  return value;
}

function verifyToken(token: string): boolean {
  const secret = getEnvVar("JWT_SECRET");
  const [header, payload, signature] = token.split(".");

  if (!header || !payload || !signature) {
    return false;
  }

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST requests to /api/notes
  if (req.method !== "POST" || !req.path.startsWith("/api/notes")) {
    next();
    return;
  }

  const authHeader = req.header("Authorization");

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid Authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!verifyToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}"
}

