import { db, deleteNote, getAllNotes, getNoteById, insertNote, updateNote } from "../db/notes-table";

export const router = Router();

// GET /notes - Retrieve all notes
router.get("/notes", (req: Request, res: Response) => {
  try {
    const notes = getAllNotes();
    res.json(notes);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve notes" });
  }
});

// GET /notes/:id - Retrieve a specific note by ID
router.get("/notes/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid note ID" });
    }

    const note = getNoteById(id);
    if (!note) {
      return res.status(404).json({ error: "Note not found" });
    }

    res.json(note);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve note" });
  }
});

// POST /notes - Create a new note
router.post("/notes", (req: Request, res: Response) => {
  try {
    const { content, timestamp, visible } = req.body;

    if (typeof content !== "string" || typeof timestamp !== "number" || typeof visible !== "boolean") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const id = insertNote(content, timestamp, visible);
    const newNote = getNoteById(id);

    if (!newNote) {
      return res.status(500).json({ error: "Failed to create note" });
    }

    res.status(201).json(newNote);
  } catch (error) {
    res.status(500).json({ error: "Failed to create note" });
  }
});

// PUT /notes/:id - Update an existing note
router.put("/notes/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid note ID" });
    }

    const { content, timestamp, visible } = req.body;

    if (typeof content !== "string" || typeof timestamp !== "number" || typeof visible !== "boolean") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    updateNote(id, content, timestamp, visible);
    const updatedNote = getNoteById(id);

    if (!updatedNote) {
      return res.status(404).json({ error: "Note not found" });
    }

    res.json(updatedNote);
  } catch (error) {
    res.status(500).json({ error: "Failed to update note" });
  }
});

// DELETE /notes/:id - Delete a note
router.delete("/notes/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid note ID" });
    }

    deleteNote(id);
    res.json({ message: "Note deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete note" });
  }
});"
}

