{
  "code": "import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware runs on every request, but we only enforce tracking/profiling
  // restrictions on search-related endpoints that might collect user data.

  // Allow all non-search routes to proceed normally
  if (!req.path.startsWith('/search')) {
    next();
    return;
  }

  // For search routes, ensure no tracking or profiling data is collected
  // Check for common tracking headers and remove them
  const trackingHeaders = [
    'X-Forwarded-For',
    'X-Real-IP',
    'User-Agent',
    'Referer',
    'Accept-Language',
    'Accept-Encoding',
    'DNT',
    'Sec-Fetch-Dest',
    'Sec-Fetch-Mode',
    'Sec-Fetch-Site',
    'Sec-Fetch-User'
  ];

  // Remove tracking headers from the request
  for (const header of trackingHeaders) {
    delete req.headers[header];
    delete req.headers[header.toLowerCase()];
  }

  // Ensure no profiling data is present in query params or body
  // Clear sensitive query parameters
  const sensitiveParams = ['user_id', 'session_id', 'tracking_id', 'profile_data'];

  // Remove sensitive query parameters
  if (req.query) {
    for (const param of sensitiveParams) {
      delete req.query[param];
    }
  }

  // Clear sensitive body fields if present
  if (req.body && typeof req.body === 'object') {
    for (const param of sensitiveParams) {
      delete req.body[param];
    }
  }

  // Continue processing the request
  next();
}"
}

