    status TEXT,
    validUntil TEXT
  );
`;

db.exec(createTables);

export function getAllInvoices(): Invoice[] {
  const stmt = db.prepare("SELECT * FROM invoices");
  return stmt.all() as unknown as Invoice[];
}

export function getInvoiceById(id: number): Invoice | undefined {
  const stmt = db.prepare("SELECT * FROM invoices WHERE id = ?");
  return stmt.get(id) as unknown as Invoice | undefined;
}

export function insertInvoice(
  clientId: number,
  title: string,
  description: string,
  amount: number,
  status: "draft" | "sent" | "paid" | "overdue",
  dueDate: string
): number {
  const stmt = db.prepare(
    "INSERT INTO invoices (clientId, title, description, amount, status, dueDate) VALUES (?, ?, ?, ?, ?, ?)"
  );
  const result = stmt.run(clientId, title, description, amount, status, dueDate);
  return Number(result.lastInsertRowid);
}

export function updateInvoice(
  id: number,
  clientId: number,
  title: string,
  description: string,
  amount: number,
  status: "draft" | "sent" | "paid" | "overdue",
  dueDate: string
): void {
  const stmt = db.prepare(
    "UPDATE invoices SET clientId = ?, title = ?, description = ?, amount = ?, status = ?, dueDate = ? WHERE id = ?"
  );
  stmt.run(clientId, title, description, amount, status, dueDate, id);
}

