  "code": "import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    // Decode payload (basic base64url decoding)
    const payloadStr = Buffer.from(payload, "base64url").toString("utf8");
    const payloadObj = JSON.parse(payloadStr);

    // Check role
    if (payloadObj.role === "admin") {
      req.role = "admin" as any; // Type assertion needed due to dynamic nature
    } else if (payloadObj.role === "client") {
      req.role = "client" as any; // Type assertion needed due to dynamic nature
    } else {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
  }
}"
}

