export function TimerDashboard() {
  const [timeEntries, setTimeEntries] = useState<TimeEntry[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [newEntry, setNewEntry] = useState({
    projectId: "",
    description: "",
    tags: ""
  });

  const [activeEntryId, setActiveEntryId] = useState<string | null>(null);

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    try {
      setLoading(true);
      const [entriesRes, projectsRes] = await Promise.all([
        fetch("/api/time-tracking-api/"),
        fetch("/api/time-tracking-api/projects")
      ]);

      if (!entriesRes.ok || !projectsRes.ok) {
        throw new Error("Failed to fetch data");
      }

      const entries = await entriesRes.json();
      const projects = await projectsRes.json();

      setTimeEntries(entries);
      setProjects(projects);

    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const startTimer = async () => {
    if (!newEntry.projectId || !newEntry.description) return;

    try {
      const res = await fetch("/api/time-tracking-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...newEntry,
          tags: newEntry.tags.split(",").map(tag => tag.trim()).filter(tag => tag)
        })
      });

      if (!res.ok) throw new Error("Failed to start timer");

      const createdEntry = await res.json();
      setTimeEntries(prev => [...prev, createdEntry]);

      setNewEntry({
        projectId: "",
        description: "",
        tags: ""
      });

      setActiveEntryId(createdEntry.id);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const stopTimer = async (id: string) => {
    try {
      const res = await fetch(`/api/time-tracking-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ endTime: new Date().toISOString() })
      });

      if (!res.ok) throw new Error("Failed to stop timer");

      const updatedEntry = await res.json();
      setTimeEntries(prev => 
        prev.map(entry => entry.id === id ? updatedEntry : entry)
      );

      if (activeEntryId === id) {
        setActiveEntryId(null);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const deleteEntry = async (id: string) => {
    try {
      const res = await fetch(`/api/time-tracking-api/${id}`, {
        method: "DELETE"
      });

      if (!res.ok) throw new Error("Failed to delete entry");

      setTimeEntries(prev => prev.filter(entry => entry.id !== id));

      if (activeEntryId === id) {
        setActiveEntryId(null);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  const activeEntry = timeEntries.find(entry => entry.id === activeEntryId);

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Time Tracker</h1>

      <div style={{ marginBottom: "30px", padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>New Entry</h2>
        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Project:</label>
          <select
            value={newEntry.projectId}
            onChange={(e) => setNewEntry({...newEntry, projectId: e.target.value})}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select a project</option>
            {projects.map(project => (
              <option key={project.id} value={project.id}>{project.name}</option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Description:</label>
          <input
            type="text"
            value={newEntry.description}
            onChange={(e) => setNewEntry({...newEntry, description: e.target.value})}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            placeholder="What did you work on?"
          />
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Tags (comma separated):</label>
          <input
            type="text"
            value={newEntry.tags}
            onChange={(e) => setNewEntry({...newEntry, tags: e.target.value})}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            placeholder="Work, Meeting, Coding"
          />
        </div>

        <button
          onClick={startTimer}
          disabled={!newEntry.projectId || !newEntry.description}
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "10px 15px",
            borderRadius: "4px",
            cursor: "pointer",
            width: "100%"
          }}
        >
          Start Timer
        </button>
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Active Timer</h2>
        {activeEntry ? (
          <div style={{ padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
            <p><strong>Description:</strong> {activeEntry.description}</p>
            <p><strong>Project:</strong> {projects.find(p => p.id === activeEntry.projectId)?.name || "Unknown"}</p>
            <p><strong>Started:</strong> {new Date(activeEntry.startTime).toLocaleString()}</p>
            <p><strong>Tags:</strong> {activeEntry.tags.join(", ") || "None"}</p>
            <button
              onClick={() => stopTimer(activeEntry.id)}
              style={{
                backgroundColor: "#dc3545",
                color: "white",
                border: "none",
                padding: "10px 15px",
                borderRadius: "4px",
                cursor: "pointer",
                marginTop: "10px"
              }}
            >
              Stop Timer
            </button>
          </div>
        ) : (
          <p>No active timer</p>
        )}
      </div>

      <div>
        <h2>Recent Entries</h2>
        {timeEntries.length === 0 ? (
          <p>No time entries yet</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {timeEntries.map(entry => {
              const project = projects.find(p => p.id === entry.projectId);
              return (
                <div 
                  key={entry.id} 
                  style={{ 
                    padding: "15px", 
                    border: "1px solid #ccc", 
                    borderRadius: "8px",
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center"
                  }}
                >
                  <div>
                    <p><strong>{entry.description}</strong></p>
                    <p>Project: {project?.name || "Unknown"}</p>
                    <p>Tags: {entry.tags.join(", ") || "None"}</p>
                    <p>Duration: {entry.endTime ? 
                      Math.floor((new Date(entry.endTime).getTime() - new Date(entry.startTime).getTime()) / 1000 / 60) + " minutes"
                      : "Active"}</p>
                  </div>
                  <div style={{ display: "flex", gap: "5px" }}>
                    {entry.endTime ? null : (
                      <button
                        onClick={() => stopTimer(entry.id)}
                        style={{
                          backgroundColor: "#dc3545",
                          color: "white",
                          border: "none",
                          padding: "5px 10px",
                          borderRadius: "4px",
                          cursor: "pointer"
                        }}
                      >
                        Stop
                      </button>
                    )}
                    <button
                      onClick={() => deleteEntry(entry.id)}
                      style={{
                        backgroundColor: "#6c757d",
                        color: "white",
                        border: "none",
                        padding: "5px 10px",
                        borderRadius: "4px",
                        cursor: "pointer"
                      }}
                    >
                      Delete
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}"
}

