export const db = new DatabaseSync(":memory:");

interface Bookmark {
  id: number;
  title: string;
  url: string;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
}

interface Tag {
  id: number;
  name: string;
}

interface BookmarkTag {
  bookmarkId: number;
  tagId: number;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS bookmarks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    url TEXT NOT NULL,
    notes TEXT,
    createdAt TEXT NOT NULL,
    updatedAt TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS tags (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT UNIQUE NOT NULL
  );

  CREATE TABLE IF NOT EXISTS bookmark_tags (
    bookmarkId INTEGER,
    tagId INTEGER,
    FOREIGN KEY (bookmarkId) REFERENCES bookmarks(id) ON DELETE CASCADE,
    FOREIGN KEY (tagId) REFERENCES tags(id) ON DELETE CASCADE,
    PRIMARY KEY (bookmarkId, tagId)
  );
`;

db.exec(initSql);

export function getAllBookmarks(): Bookmark[] {
  const stmt = db.prepare(`
    SELECT id, title, url, notes, createdAt, updatedAt
    FROM bookmarks
    ORDER BY createdAt DESC
  `);
  return stmt.all() as unknown as Bookmark[];
}

export function getBookmarkById(id: number): Bookmark | undefined {
  const stmt = db.prepare(`
    SELECT id, title, url, notes, createdAt, updatedAt
    FROM bookmarks
    WHERE id = ?
  `);
  return stmt.get(id) as unknown as Bookmark | undefined;
}

export function createBookmark(
  title: string,
  url: string,
  notes: string | null
): number {
  const now = new Date().toISOString();
  const stmt = db.prepare(`
    INSERT INTO bookmarks (title, url, notes, createdAt, updatedAt)
    VALUES (?, ?, ?, ?, ?)
  `);
  const result = stmt.run(title, url, notes, now, now);
  return Number(result.lastInsertRowid);
}

export function updateBookmark(
  id: number,
  title: string,
  url: string,
  notes: string | null
): void {
  const now = new Date().toISOString();
  const stmt = db.prepare(`
    UPDATE bookmarks
    SET title = ?, url = ?, notes = ?, updatedAt = ?
    WHERE id = ?
  `);
  stmt.run(title, url, notes, now, id);
}

export function deleteBookmark(id: number): void {
  const stmt = db.prepare(`DELETE FROM bookmarks WHERE id = ?`);
  stmt.run(id);
}

// Seed data
if (getAllBookmarks().length === 0) {
  const bookmarkIds = [
    createBookmark("GitHub", "https://github.com", "Code repository"),
    createBookmark("MDN Web Docs", "https://developer.mozilla.org", "Web development resources"),
    createBookmark("TypeScript", "https://www.typescriptlang.org", "JavaScript with syntax highlighting"),
    createBookmark("Node.js", "https://nodejs.org", "Server-side JavaScript runtime"),
