  ];

  // Add some tags to the bookmarks
  const tagNames = ["development", "documentation", "tools", "web"];
  const tagIds: Record<string, number> = {};

  tagNames.forEach(tagName => {
    const stmt = db.prepare(`INSERT OR IGNORE INTO tags (name) VALUES (?)`);
    stmt.run(tagName);
    const result = db.prepare(`SELECT id FROM tags WHERE name = ?`).get(tagName);
    tagIds[tagName] = Number(result.id);
  });

  // Link some tags to bookmarks
  const linkStmt = db.prepare(`
