{
  "code": "import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process login-related requests
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  // Check for JWT in Authorization header
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith("Bearer ")) {
    const token = authHeader.substring(7);
    if (!process.env.JWT_SECRET) {
      res.status(500).json({ error: "Server configuration error" });
      return;
    }

    const secret = Buffer.from(process.env.JWT_SECRET, "utf-8");
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Token is valid, proceed
    next();
    return;
  }

  // For non-JWT requests, check if we have username/password or OAuth data
  if (req.body && (req.body.username || req.body.google || req.body.github || req.body.ldap || req.body.proxy)) {
    // In a real implementation, this would validate credentials against respective services
    // For now, we'll just pass through to allow further processing
    next();
    return;
  }

  // If no valid authentication method provided, reject
  res.status(401).json({ error: "Authentication required" });
}"
}

{
  "code": "import { useEffect, useState } from "react";

interface Book {
  id: string;
  title: string;
  author: string;
  isbn?: string;
  shelf?: string;
}

export function LibraryBrowser() {
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newBook, setNewBook] = useState({
    title: "",
    author: "",
    isbn: "",
    shelf: "",
  });

  useEffect(() => {
    fetchBooks();
  }, []);

  const fetchBooks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/library-service/");
      if (!response.ok) {
        throw new Error(`Failed to fetch books: ${response.status}`);
      }
      const data = await response.json();
      setBooks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddBook = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/library-service/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newBook),
      });
      if (!response.ok) {
        throw new Error(`Failed to add book: ${response.status}`);
      }
      setNewBook({ title: "", author: "", isbn: "", shelf: "" });
      fetchBooks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleMoveBook = async (id: string, shelf: string) => {
    try {
      const response = await fetch(`/api/library-service/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ shelf }),
      });
      if (!response.ok) {
        throw new Error(`Failed to move book: ${response.status}`);
      }
      fetchBooks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteBook = async (id: string) => {
    try {
      const response = await fetch(`/api/library-service/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete book: ${response.status}`);
      }
      fetchBooks();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center" }}>{error}</div>;

  return (
    <div style={containerStyle}>
      <h1>My Ebook Library</h1>

      <div style={formContainerStyle}>
        <h2>Add New Book</h2>
        <form onSubmit={handleAddBook}>
          <input
            type="text"
            placeholder="Title"
            value={newBook.title}
            onChange={(e) => setNewBook({...newBook, title: e.target.value})}
            style={inputStyle}
            required
          />
          <input
            type="text"
            placeholder="Author"
            value={newBook.author}
            onChange={(e) => setNewBook({...newBook, author: e.target.value})}
            style={inputStyle}
            required
          />
          <input
            type="text"
            placeholder="ISBN (optional)"
            value={newBook.isbn}
            onChange={(e) => setNewBook({...newBook, isbn: e.target.value})}
            style={inputStyle}
          />
          <input
            type="text"
            placeholder="Shelf (optional)"
            value={newBook.shelf}
            onChange={(e) => setNewBook({...newBook, shelf: e.target.value})}
            style={inputStyle}
          />
          <button type="submit" style={buttonStyle}>Add Book</button>
        </form>
      </div>

      <h2>Book Collection</h2>
      {books.length === 0 ? (
        <p style={{ textAlign: "center" }}>No books found. Add some books to get started!</p>
      ) : (
        <div style={gridStyle}>
          {books.map((book) => (
            <div key={book.id} style={cardStyle}>
              <h3>{book.title}</h3>
              <p>by {book.author}</p>
              {book.isbn && <p>ISBN: {book.isbn}</p>}
              <p>Shelf: {book.shelf || "Unshelved"}</p>
              <div style={{ display: "flex", gap: "5px", flexWrap: "wrap" }}>
                <select
                  value={book.shelf || ""}
                  onChange={(e) => handleMoveBook(book.id, e.target.value)}
                  style={{ ...buttonStyle, flex: 1 }}
                >
                  <option value="">Move to Shelf</option>
                  <option value="Fiction">Fiction</option>
                  <option value="Non-Fiction">Non-Fiction</option>
                  <option value="Science Fiction">Science Fiction</option>
                  <option value="Biography">Biography</option>
                </select>
                <button
                  onClick={() => handleDeleteBook(book.id)}
                  style={{ ...buttonStyle, backgroundColor: "#ff4d4d" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

