import { db, deleteBook, getAllBooks, getBookById, insertBook, updateBook } from "../db/book-library-database";
import { middleware } from "../middleware/multi-method-login";

export const router = Router();

// GET /books - Retrieve all books
router.get("/books", (req: Request, res: Response) => {
  try {
    const books = getAllBooks();
    res.json(books);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve books" });
  }
});

// GET /books/:id - Retrieve a specific book by ID
router.get("/books/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const book = getBookById(id);
    if (!book) {
      return res.status(404).json({ error: "Book not found" });
    }
    res.json(book);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve book" });
  }
});

// POST /books - Create a new book
router.post("/books", middleware, (req: Request, res: Response) => {
  try {
    const { title, author, publicationYear, genre, pageCount, description } = req.body;

    // Validate required fields
    if (!title || !author) {
      return res.status(400).json({ error: "Title and author are required" });
    }

    const newBookId = insertBook({
      title,
      author,
      publicationYear: publicationYear ? Number(publicationYear) : undefined,
      genre: genre || undefined,
      pageCount: pageCount ? Number(pageCount) : undefined,
      description: description || undefined
    });

    const createdBook = getBookById(newBookId);
    if (!createdBook) {
      return res.status(500).json({ error: "Failed to retrieve created book" });
    }

    res.status(201).json(createdBook);
  } catch (error) {
    res.status(500).json({ error: "Failed to create book" });
  }
});

// PUT /books/:id - Update an existing book
router.put("/books/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { title, author, publicationYear, genre, pageCount, description } = req.body;

    const book = getBookById(id);
    if (!book) {
      return res.status(404).json({ error: "Book not found" });
    }

    const updated = updateBook(id, {
      title: title !== undefined ? title : book.title,
      author: author !== undefined ? author : book.author,
      publicationYear: publicationYear !== undefined ? Number(publicationYear) : book.publicationYear,
      genre: genre !== undefined ? genre : book.genre,
      pageCount: pageCount !== undefined ? Number(pageCount) : book.pageCount,
      description: description !== undefined ? description : book.description
    });

    if (!updated) {
      return res.status(500).json({ error: "Failed to update book" });
    }

    const updatedBook = getBookById(id);
    if (!updatedBook) {
      return res.status(500).json({ error: "Failed to retrieve updated book" });
    }

    res.json(updatedBook);
  } catch (error) {
    res.status(500).json({ error: "Failed to update book" });
  }
});

// DELETE /books/:id - Delete a book
router.delete("/books/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const deleted = deleteBook(id);

    if (!deleted) {
      return res.status(404).json({ error: "Book not found" });
    }

    res.json({ message: "Book deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete book" });
  }
});"
}

