  "code": "import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/selfhosted-newsletter-tool.db"
);

interface Subscriber {
  id: number;
  email: string;
  subscribed_at: string;
}

const createSubscribersTable = `
  CREATE TABLE IF NOT EXISTS subscribers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT UNIQUE NOT NULL,
    subscribed_at TEXT NOT NULL
  )
`;

db.exec(createSubscribersTable);

export const getAllSubscribers = (): Subscriber[] => {
  const stmt = db.prepare(`SELECT * FROM subscribers`);
  return stmt.all() as unknown as Subscriber[];
};

export const getSubscriberById = (id: number): Subscriber | undefined => {
  const stmt = db.prepare(`SELECT * FROM subscribers WHERE id = ?`);
  return stmt.get(id) as unknown as Subscriber | undefined;
};

export const insertSubscriber = (
  email: string,
  subscribedAt: string
): number => {
  const stmt = db.prepare(
    `INSERT INTO subscribers (email, subscribed_at) VALUES (?, ?)`
  );
  const result = stmt.run(email, subscribedAt);
  return Number(result.lastInsertRowid);
};

export const updateSubscriber = (
  id: number,
  email: string,
  subscribedAt: string
): number => {
  const stmt = db.prepare(
    `UPDATE subscribers SET email = ?, subscribed_at = ? WHERE id = ?`
  );
  const result = stmt.run(email, subscribedAt, id);
  return Number(result.changes);
};

export const deleteSubscriber = (id: number): number => {
  const stmt = db.prepare(`DELETE FROM subscribers WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
};

