export const db = new DatabaseSync(
  "/tmp/git-service.db"
);

interface Repository {
  id: number;
  name: string;
  description: string;
  owner_id: number;
  created_at: string;
  updated_at: string;
}

interface Issue {
  id: number;
  repository_id: number;
  title: string;
  description: string;
  author_id: number;
  status: "open" | "closed";
  created_at: string;
  updated_at: string;
}

interface PullRequest {
  id: number;
  repository_id: number;
  title: string;
  description: string;
  author_id: number;
  status: "open" | "closed" | "merged";
  created_at: string;
  updated_at: string;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS repositories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    owner_id INTEGER NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS issues (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    repository_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    author_id INTEGER NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('open', 'closed')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS pull_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    repository_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    author_id INTEGER NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('open', 'closed', 'merged')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
`;

db.exec(initSql);

export function getAllRepositories(): Repository[] {
  const stmt = db.prepare(
    "SELECT * FROM repositories ORDER BY created_at DESC"
  );
  return stmt.all() as unknown as Repository[];
}

export function getRepositoryById(id: number): Repository | undefined {
  const stmt = db.prepare(
    "SELECT * FROM repositories WHERE id = ?"
  );
  return stmt.get(id) as unknown as Repository | undefined;
}

export function insertRepository(
  name: string,
  description: string,
  owner_id: number
): number {
  const stmt = db.prepare(
    "INSERT INTO repositories (name, description, owner_id, created_at, updated_at) VALUES (?, ?, ?, datetime('now'), datetime('now'))"
  );
  const result = stmt.run(name, description, owner_id);
  return Number(result.lastInsertRowid);
}

export function updateRepository(
  id: number,
  name: string,
  description: string
): void {
  const stmt = db.prepare(
    "UPDATE repositories SET name = ?, description = ?, updated_at = datetime('now') WHERE id = ?"
  );
  stmt.run(name, description, id);
}

export function deleteRepository(id: number): void {
  const stmt = db.prepare(
    "DELETE FROM repositories WHERE id = ?"
  );
  stmt.run(id);
}

// Sample data initialization
if (getAllRepositories().length === 0) {
  const repo1Id = insertRepository(
    "frontend-app",
    "A modern web application",
    1
  );
  const repo2Id = insertRepository(
    "backend-api",
    "RESTful API service",
    2
  );
  const repo3Id = insertRepository(
    "mobile-app",
    "Cross-platform mobile app",
    1
  );

  // Insert some sample issues
  const issueStmt = db.prepare(
    "INSERT INTO issues (repository_id, title, description, author_id, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))"
  );
  issueStmt.run(repo1Id, "Login page broken", "User can't login after password reset.", 1, "open");
  issueStmt.run(repo2Id, "Slow database queries", "API response times are too long.", 2, "open");

  // Insert some sample pull requests
  const prStmt = db.prepare(
    "INSERT INTO pull_requests (repository_id, title, description, author_id, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))"
  );
  prStmt.run(repo1Id, "Fix login bug", "This PR fixes the login issue.", 1, "open");
  prStmt.run(repo2Id, "Optimize queries", "Improved performance of database queries.", 2, "merged");
}"
}

{
    "code": "import { Router, type Request, type Response } from "express";
import { db, deleteRepository, getAllRepositories, getRepositoryById, insertRepository, updateRepository } from "../db/repositories-table";

export const router = Router();

// Get all repositories
router.get("/repositories", (req: Request, res: Response) => {
  try {
    const repositories = getAllRepositories();
    res.json(repositories);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch repositories" });
  }
});

// Get a repository by ID
router.get("/repositories/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const repository = getRepositoryById(id);

    if (!repository) {
      return res.status(404).json({ error: "Repository not found" });
    }

    res.json(repository);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch repository" });
  }
});

// Create a new repository
router.post("/repositories", (req: Request, res: Response) => {
  try {
    const { name, description, owner_id } = req.body;

    if (!name || !owner_id) {
      return res.status(400).json({ error: "Name and owner_id are required" });
    }

    const id = insertRepository(name, description || "", owner_id);
    const newRepository = getRepositoryById(id);

    if (!newRepository) {
      return res.status(500).json({ error: "Failed to create repository" });
    }

    res.status(201).json(newRepository);
  } catch (error) {
    res.status(500).json({ error: "Failed to create repository" });
  }
});

// Update a repository
router.put("/repositories/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { name, description } = req.body;

    if (!name) {
      return res.status(400).json({ error: "Name is required" });
    }

    const existingRepo = getRepositoryById(id);

    if (!existingRepo) {
      return res.status(404).json({ error: "Repository not found" });
    }

    updateRepository(id, name, description || "");
    const updatedRepo = getRepositoryById(id);

    if (!updatedRepo) {
      return res.status(500).json({ error: "Failed to update repository" });
    }

    res.json(updatedRepo);
  } catch (error) {
    res.status(500).json({ error: "Failed to update repository" });
  }
});

// Delete a repository
router.delete("/repositories/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    const existingRepo = getRepositoryById(id);

    if (!existingRepo) {
      return res.status(404).json({ error: "Repository not found" });
    }

    deleteRepository(id);
    res.json({ message: "Repository deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete repository" });
  }
});"
}

