  "code": "import type { Request, Response, NextFunction } from "express";

/**
 * Middleware to guard payment gateway requests and ensure they are made over HTTPS.
 * This middleware should be mounted globally to protect all payment-related routes.
 */
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check HTTPS for payment-related routes
  if (!req.path.startsWith('/payment')) {
    next();
    return;
  }

  // Check if the request is made over HTTPS
  if (req.protocol !== 'https') {
    res.status(403).json({
      error: 'Payment processing requires a secure HTTPS connection.'
    });
    return;
  }

  // If we reach here, the request is secure and payment-related
  next();
}"
}

{
  "code": "import { useEffect, useState } from "react";

interface Invoice {
  id: string;
  clientId: string;
  amount: number;
  status: "pending" | "paid" | "overdue";
  dueDate: string;
}

interface Client {
  id: string;
  name: string;
  email: string;
}

export function InvoicingDashboard() {
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchAllData() {
      try {
        setLoading(true);
        const [invoicesRes, clientsRes] = await Promise.all([
          fetch("/api/invoicing-api/invoices"),
          fetch("/api/invoicing-api/clients")
        ]);

        if (!invoicesRes.ok || !clientsRes.ok) {
          throw new Error(`Failed to fetch data: ${invoicesRes.status}, ${clientsRes.status}`);
        }

        const invoicesData = await invoicesRes.json();
        const clientsData = await clientsRes.json();

        setInvoices(invoicesData);
        setClients(clientsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchAllData();
  }, []);

  const handleDeleteInvoice = async (id: string) => {
    try {
      const res = await fetch(`/api/invoicing-api/invoices/${id}`, {
        method: "DELETE"
      });

      if (!res.ok) {
        throw new Error(`Failed to delete invoice: ${res.status}`);
      }

      // Refresh data
      const res2 = await fetch("/api/invoicing-api/invoices");
      if (!res2.ok) {
        throw new Error(`Failed to refresh invoices: ${res2.status}`);
      }

      const updatedInvoices = await res2.json();
      setInvoices(updatedInvoices);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { year: "numeric", month: "short", day: "numeric" };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  const getClientName = (clientId: string) => {
    const client = clients.find(c => c.id === clientId);
    return client ? client.name : "Unknown Client";
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Invoicing Dashboard</h1>

      <h2>Invoices</h2>
      {invoices.length === 0 ? (
        <p style={{ textAlign: "center" }}>No invoices found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {invoices.map(invoice => (
            <div key={invoice.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <strong>{getClientName(invoice.clientId)}</strong>
                <br />
                <span>${invoice.amount.toFixed(2)}</span>
                <br />
                <span>Status: {invoice.status}</span>
                <br />
                <span>Due: {formatDate(invoice.dueDate)}</span>
              </div>
              <button 
                onClick={() => handleDeleteInvoice(invoice.id)}
                style={{ backgroundColor: "#ff4d4d", color: "white", border: "none", borderRadius: "4px", padding: "8px 12px", cursor: "pointer" }}
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      )}

      <h2>Clients</h2>
      {clients.length === 0 ? (
        <p style={{ textAlign: "center" }}>No clients found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {clients.map(client => (
            <div key={client.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
              <strong>{client.name}</strong>
              <br />
              <span>{client.email}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}"
}

