export const db = new DatabaseSync("complaints.db");

interface ComplaintRow {
  id: number;
  text: string;
  status: string;
  created_at: string;
  updated_at: string;
}

interface AuditLogRow {
  id: number;
  complaint_id: number;
  action: string;
  performed_by: string;
  timestamp: string;
}

const createComplaintsTable = `
  CREATE TABLE IF NOT EXISTS complaints (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    text TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
`;

const createAuditLogTable = `
  CREATE TABLE IF NOT EXISTS audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    complaint_id INTEGER NOT NULL,
    action TEXT NOT NULL,
    performed_by TEXT NOT NULL,
    timestamp TEXT NOT NULL,
    FOREIGN KEY (complaint_id) REFERENCES complaints (id)
  );
`;

export function getAllComplaints(): ComplaintRow[] {
  const stmt = db.prepare(`SELECT * FROM complaints ORDER BY created_at DESC`);
  return stmt.all() as unknown as ComplaintRow[];
}

export function getComplaintById(id: number): ComplaintRow | undefined {
  const stmt = db.prepare(`SELECT * FROM complaints WHERE id = ?`);
  return stmt.get(id) as unknown as ComplaintRow | undefined;
}

export function insertComplaint(text: string, status: string, created_at: string, updated_at: string): number {
  const stmt = db.prepare(
    `INSERT INTO complaints (text, status, created_at, updated_at) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(text, status, created_at, updated_at);
  return Number(result.lastInsertRowid);
}

export function updateComplaint(id: number, text: string, status: string, updated_at: string): void {
  const stmt = db.prepare(
    `UPDATE complaints SET text = ?, status = ?, updated_at = ? WHERE id = ?`
  );
  stmt.run(text, status, updated_at, id);
}

export function deleteComplaint(id: number): void {
  const stmt = db.prepare(`DELETE FROM complaints WHERE id = ?`);
  stmt.run(id);
}

export function getAllAuditLogs(): AuditLogRow[] {
  const stmt = db.prepare(`SELECT * FROM audit_log ORDER BY timestamp DESC`);
  return stmt.all() as unknown as AuditLogRow[];
}

export function getAuditLogsByComplaintId(complaint_id: number): AuditLogRow[] {
  const stmt = db.prepare(`SELECT * FROM audit_log WHERE complaint_id = ? ORDER BY timestamp DESC`);
  return stmt.all(complaint_id) as unknown as AuditLogRow[];
}

export function insertAuditLog(complaint_id: number, action: string, performed_by: string, timestamp: string): number {
  const stmt = db.prepare(
    `INSERT INTO audit_log (complaint_id, action, performed_by, timestamp) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(complaint_id, action, performed_by, timestamp);
  return Number(result.lastInsertRowid);
}

// Initialize tables
if (db.prepare(`SELECT name FROM sqlite_master WHERE type='table' AND name='complaints'`).get() === undefined) {
