export const db = new DatabaseSync("food-truck-planner.db");

interface Route {
  id: number;
  driverId: number;
  date: string;
  locationsVisited: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS routes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    driverId INTEGER NOT NULL,
    date TEXT NOT NULL,
    locationsVisited TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRoutes(): Route[] {
  const stmt = db.prepare("SELECT * FROM routes");
  return stmt.all() as unknown as Route[];
}

export function getRouteById(id: number): Route | undefined {
  const stmt = db.prepare("SELECT * FROM routes WHERE id = ?");
  return stmt.get(id) as unknown as Route | undefined;
}

export function insertRoute(route: Omit<Route, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO routes (driverId, date, locationsVisited) VALUES (?, ?, ?)"
  );
  const result = stmt.run(route.driverId, route.date, route.locationsVisited);
  return Number(result.lastInsertRowid);
}

export function updateRoute(id: number, route: Partial<Route>): boolean {
  const fields = [];
  const values = [];

  if (route.driverId !== undefined) {
    fields.push("driverId = ?");
    values.push(route.driverId);
  }

  if (route.date !== undefined) {
    fields.push("date = ?");
    values.push(route.date);
  }

  if (route.locationsVisited !== undefined) {
    fields.push("locationsVisited = ?");
    values.push(route.locationsVisited);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE routes SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteRoute(id: number): boolean {
  const stmt = db.prepare("DELETE FROM routes WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

