{
  "code": "import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as authRouter } from "../routes/auth-service";
import { router as apiRouter } from "../routes/routes-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the revenue dashboard
  if (req.method !== "POST" || !req.path.startsWith("/revenue")) {
    next();
    return;
  }

  // Check if the user is the owner
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  try {
    // Simple verification logic - in a real app, you'd decode and verify the JWT properly
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (actualSignature.length !== expectedSignature.length) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const isValid = timingSafeEqual(expectedSignature, actualSignature);

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    // In a real implementation, we would verify the payload and check ownership
    // For now, we'll just allow access
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
  }
}"
}

