    "code": "import { Router, type Request, type Response } from "express";
import { db as routesDb, deleteRoute, getAllRoutes, getRouteById, insertRoute, updateRoute } from "../db/routes-table";
import { db as revenueDb, getTotalRevenue } from "../db/revenue-total-view";
import { middleware as revenueGuard } from "../middleware/revenue-guard";

export const router = Router();

// Get all routes
router.get("/", (req: Request, res: Response) => {
  try {
    const routes = getAllRoutes();
    return res.json(routes);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch routes" });
  }
});

// Get a specific route by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid route ID" });
    }

    const route = getRouteById(id);
    if (!route) {
      return res.status(404).json({ error: "Route not found" });
    }

    return res.json(route);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch route" });
  }
});

// Create a new route
router.post("/", (req: Request, res: Response) => {
  try {
    const { driverId, truckId, date, startLocation, endLocation, revenue } = req.body;

    // Validate required fields
    if (!driverId || !date || !startLocation || !endLocation) {
      return res.status(400).json({ error: "Missing required fields: driverId, date, startLocation, endLocation" });
    }

    const newRoute = {
      driverId,
      date,
      startLocation,
      endLocation,
      revenue: revenue ?? 0
    };

    const insertedId = insertRoute(newRoute);

    // Fetch the inserted route to return it
    const route = getRouteById(insertedId);
    if (!route) {
      return res.status(500).json({ error: "Failed to retrieve created route" });
    }

    return res.status(201).json(route);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create route" });
  }
});

// Update an existing route
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid route ID" });
    }

    const { driverId, date, startLocation, endLocation, revenue } = req.body;

    const routeData = {
      driverId,
      date,
      startLocation,
      endLocation,
      revenue
    };

    const updated = updateRoute(id, routeData);

    if (!updated) {
      return res.status(404).json({ error: "Route not found" });
    }

    const updatedRoute = getRouteById(id);
    if (!updatedRoute) {
      return res.status(500).json({ error: "Failed to retrieve updated route" });
    }

    return res.json(updatedRoute);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update route" });
  }
});

// Delete a route
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid route ID" });
    }

    const deleted = deleteRoute(id);

    if (!deleted) {
      return res.status(404).json({ error: "Route not found" });
    }

    return res.json({ message: "Route deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete route" });
  }
});

// Get total revenue
router.get("/revenue", revenueGuard, (req: Request, res: Response) => {
  try {
    const totalRevenue = getTotalRevenue();
    return res.json(totalRevenue);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch total revenue" });
  }
});"
}

