export const db = new DatabaseSync("library.db");

interface Checkout {
  id: number;
  studentId: number;
  bookIsbn: string;
  dueDate: string;
  returnDate?: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS checkouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    studentId INTEGER NOT NULL,
    bookIsbn TEXT NOT NULL,
    dueDate TEXT NOT NULL,
    returnDate TEXT
  );
`;

db.exec(createTableSql);

export function getAllCheckouts(): Checkout[] {
  const stmt = db.prepare("SELECT * FROM checkouts");
  return stmt.all() as unknown as Checkout[];
}

export function getCheckoutById(id: number): Checkout | undefined {
  const stmt = db.prepare("SELECT * FROM checkouts WHERE id = ?");
  return stmt.get(id) as unknown as Checkout | undefined;
}

export function insertCheckout(
  studentId: number,
  bookIsbn: string,
  dueDate: string,
  returnDate: string | null | undefined
): number {
  const stmt = db.prepare(
    "INSERT INTO checkouts (studentId, bookIsbn, dueDate, returnDate) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(studentId, bookIsbn, dueDate, returnDate);
  return Number(result.lastInsertRowid);
}

export function updateCheckout(
  id: number,
  studentId: number,
  bookIsbn: string,
  dueDate: string,
  returnDate: string | null | undefined
): void {
  const stmt = db.prepare(
    "UPDATE checkouts SET studentId = ?, bookIsbn = ?, dueDate = ?, returnDate = ? WHERE id = ?"
  );
  stmt.run(studentId, bookIsbn, dueDate, returnDate, id);
}

export function deleteCheckout(id: number): void {
  const stmt = db.prepare("DELETE FROM checkouts WHERE id = ?");
  stmt.run(id);
}

