import { Router } from "express";
import { router as checkoutsRouter } from "../routes/checkouts-api";
import { router as waiversRouter } from "../routes/waivers-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process waiver-related requests
  if (!(req.path.startsWith("/waivers") && req.method === "POST")) {
    next();
    return;
  }

  // Check if user is a librarian
  const userRole = req.headers["x-user-role"];
  if (userRole !== "librarian") {
    res.status(403).json({ error: "Access denied. Librarian role required." });
    return;
  }

  next();
}"
}

