              <tr style={{ borderBottom: "1px solid #ccc" }}>
                <th style={{ textAlign: "left", padding: "10px" }}>Book Title</th>
                <th style={{ textAlign: "left", padding: "10px" }}>Borrower</th>
                <th style={{ textAlign: "left", padding: "10px" }}>Due Date</th>
                <th style={{ textAlign: "left", padding: "10px" }}>Fine Amount</th>
