              type="text"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
              placeholder="Enter reason for waiver"
            />
          </div>
          <div>
            <button
              onClick={() => handleWaiveFee(selectedCheckoutId, reason)}
              style={{
                backgroundColor: "#28a745",
                color: "white",
                border: "none",
                borderRadius: "4px",
                padding: "10px 20px",
                cursor: "pointer",
                marginRight: "10px",
              }}
            >
              Submit Waiver
            </button>
            <button
              onClick={() => {
                setSelectedCheckoutId(null);
                setReason("");
              }}
              style={{
                backgroundColor: "#6c757d",
                color: "white",
                border: "none",
                borderRadius: "4px",
                padding: "10px 20px",
                cursor: "pointer",
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
}"
