    "code": "import { Router, type Request, type Response } from "express";
import { db as toursDb, deleteTour, getAllTours, getTourById, insertTour, updateTour } from "../db/tours-table";
import { db as docentsDb, getAllDocents, getDocentById } from "../db/docents-table";

export const router = Router();

// Get all tours
router.get("/", (req: Request, res: Response) => {
  try {
    const tours = getAllTours();
    res.json(tours);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch tours" });
  }
});

// Get a specific tour by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid tour ID" });
  }

  const tour = getTourById(id);
  if (!tour) {
    return res.status(404).json({ error: "Tour not found" });
  }

  res.json(tour);
});

// Create a new tour
router.post("/", (req: Request, res: Response) => {
  const { docentId, tourTime, curatorId } = req.body;

  if (!docentId || !tourTime || !curatorId) {
    return res.status(400).json({ error: "Missing required fields: docentId, tourTime, curatorId" });
  }

  try {
    const newTourId = insertTour(docentId, tourTime, curatorId);
    const newTour = getTourById(newTourId);
    res.status(201).json(newTour);
  } catch (error) {
    res.status(500).json({ error: "Failed to create tour" });
  }
});

// Update an existing tour
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { docentId, tourTime, curatorId } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid tour ID" });
  }

  if (!docentId || !tourTime || !curatorId) {
    return res.status(400).json({ error: "Missing required fields: docentId, tourTime, curatorId" });
  }

  const existingTour = getTourById(id);
  if (!existingTour) {
    return res.status(404).json({ error: "Tour not found" });
  }

  try {
    updateTour(id, docentId, tourTime, curatorId);
    const updatedTour = getTourById(id);
    res.json(updatedTour);
  } catch (error) {
    res.status(500).json({ error: "Failed to update tour" });
  }
});

// Delete a tour
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid tour ID" });
  }

  const existingTour = getTourById(id);
  if (!existingTour) {
    return res.status(404).json({ error: "Tour not found" });
  }

  try {
    deleteTour(id);
    res.json({ message: "Tour deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete tour" });
  }
});"
}

