import { Router } from "express";
import { router as toursApiRouter } from "../routes/tours-api";
import { router as docentAuthRouter } from "../routes/docent-authentication";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check cancellation requests
  if (!(req.method === "DELETE" && req.path.startsWith("/tours/"))) {
    next();
    return;
  }

  // Check if user is curator
  const userRole = req.header("X-User-Role");

  if (userRole !== "curator") {
    res.status(403).json({ error: "Cancellation restricted to curators only" });
    return;
  }

  next();
}"
}

