  "code": "import { useEffect, useState } from "react";

interface Tour {
  id: string;
  date: string;
  time: string;
  groupSize: number;
  docentId: string;
}

export function CuratorDashboard() {
  const [tours, setTours] = useState<Tour[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTours();
  }, []);

  const fetchTours = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/tours-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch tours: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setTours(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCancelTour = async (id: string) => {
    try {
      const response = await fetch(`/api/tours-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to cancel tour: ${response.status} ${response.statusText}`);
      }
      // Refresh the list after cancellation
      fetchTours();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (tours.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No scheduled tours found.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px" }}>
      <h1 style={{ textAlign: "center", fontFamily: "system-ui, sans-serif" }}>
        Scheduled Tours
      </h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {tours.map((tour) => (
          <div 
            key={tour.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              fontFamily: "system-ui, sans-serif",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap"
            }}
          >
            <div>
              <strong>Date:</strong> {tour.date}<br />
              <strong>Time:</strong> {tour.time}<br />
              <strong>Group Size:</strong> {tour.groupSize}
            </div>
            <button
              onClick={() => handleCancelTour(tour.id)}
              style={{
                backgroundColor: "#ff4d4d",
                color: "white",
                border: "none",
                borderRadius: "4px",
                padding: "8px 12px",
                cursor: "pointer",
                fontFamily: "system-ui, sans-serif"
              }}
            >
              Cancel Tour
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}"
}

