import { db as toursDb } from "../db/tours-table";
import { db as docentsDb } from "../db/docents-table";
import { middleware as curatorOnlyCancellationGuard } from "../middleware/curator-only-cancellation-guard";
import { middleware as docentOnlyBookingGuard } from "../middleware/docent-only-booking-guard";

export const router = Router();

// GET /docent-authentication - List all docents
router.get("/docent-authentication", (req: Request, res: Response) => {
  try {
    const docents = docentsDb.getAllDocents();
    res.json(docents);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch docents" });
  }
});

// GET /docent-authentication/:id - Get a specific docent by ID
router.get("/docent-authentication/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const docent = docentsDb.getDocentById(id);
    if (!docent) {
      return res.status(404).json({ error: "Docent not found" });
    }
    res.json(docent);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch docent" });
  }
});

// POST /docent-authentication - Create a new docent
router.post("/docent-authentication", (req: Request, res: Response) => {
  try {
    const { name, credentials } = req.body;
    if (!name || !credentials) {
      return res.status(400).json({ error: "Name and credentials are required" });
    }
    const id = docentsDb.insertDocent(name, credentials);
    res.status(201).json({ id });
  } catch (error) {
    res.status(500).json({ error: "Failed to create docent" });
  }
});

// PUT /docent-authentication/:id - Update a docent
router.put("/docent-authentication/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { name, credentials } = req.body;
    if (!name || !credentials) {
      return res.status(400).json({ error: "Name and credentials are required" });
    }
    const existingDocent = docentsDb.getDocentById(id);
    if (!existingDocent) {
      return res.status(404).json({ error: "Docent not found" });
    }
    docentsDb.updateDocent(id, name, credentials);
    res.json({ message: "Docent updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update docent" });
  }
});

// DELETE /docent-authentication/:id - Delete a docent
router.delete("/docent-authentication/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const existingDocent = docentsDb.getDocentById(id);
    if (!existingDocent) {
      return res.status(404).json({ error: "Docent not found" });
    }
    docentsDb.deleteDocent(id);
    res.json({ message: "Docent deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete docent" });
  }
});

