import { router as toursApiRouter } from "../routes/tours-api";
import { router as docentAuthRouter } from "../routes/docent-authentication";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the tours API
  if (req.method !== "POST" || !req.path.startsWith("/api/tours")) {
    return next();
  }

  // Check if user is authenticated as a docent
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Docent authentication required" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // In a real implementation, we would verify the JWT signature here
  // For now, we'll just check if the token exists
  if (!token) {
    return res.status(401).json({ error: "Unauthorized: Invalid token" });
  }

  // If we get here, the request is authorized
  next();
}"
}

