interface Show {
  id: string;
  title: string;
}

interface Slot {
  id: string;
  time: string;
  showId: string;
}

interface Audition {
  actorId: string;
  showId: string;
  slotId: string;
}

export function AuditionSignupForm() {
  const [shows, setShows] = useState<Show[]>([]);
  const [slots, setSlots] = useState<Slot[]>([]);
  const [selectedShowId, setSelectedShowId] = useState<string | null>(null);
  const [selectedSlotId, setSelectedSlotId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    fetchShows();
  }, []);

  const fetchShows = async () => {
    try {
      const response = await fetch("/api/auditions-api/");
      if (!response.ok) throw new Error("Failed to fetch shows");
      const data = await response.json();
      setShows(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const fetchSlots = async (showId: string) => {
    try {
      const response = await fetch(`/api/auditions-api/${showId}`);
      if (!response.ok) throw new Error("Failed to fetch slots");
      const data = await response.json();
      setSlots(data);
      setSelectedShowId(showId);
      setSelectedSlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleSignup = async () => {
    if (!selectedShowId || !selectedSlotId) return;

    try {
      const response = await fetch(`/api/auditions-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          actorId: "currentActorId", // This would come from auth context in a real app
          showId: selectedShowId,
          slotId: selectedSlotId
        })
      });

      if (!response.ok) throw new Error("Failed to sign up for audition");
      setSuccess(true);
      setTimeout(() => {
        setSuccess(false);
        fetchShows();
      }, 2000);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={containerStyle}>
      <h1>Audition Signup</h1>

      {success && (
        <div style={{ backgroundColor: "lightgreen", padding: "10px", borderRadius: "5px", marginBottom: "10px" }}>
          Successfully signed up!
        </div>
      )}

      <div style={{ marginBottom: "20px" }}>
        <h2>Select a Show</h2>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
          {shows.map((show) => (
            <button
              key={show.id}
              onClick={() => fetchSlots(show.id)}
              style={showButtonStyle}
            >
              {show.title}
            </button>
          ))}
        </div>
      </div>

      {selectedShowId && (
        <div style={{ marginBottom: "20px" }}>
          <h2>Select a Time Slot</h2>
          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
            {slots.length > 0 ? (
              slots.map((slot) => (
                <button
                  key={slot.id}
                  onClick={() => setSelectedSlotId(slot.id)}
                  style={slotButtonStyle(selectedSlotId === slot.id)}
                >
                  {slot.time}
                </button>
              ))
            ) : (
              <p>No available slots</p>
            )}
          </div>
        </div>
      )}

      {selectedSlotId && (
        <button
          onClick={handleSignup}
          style={signupButtonStyle}
        >
          Sign Up for Audition
        </button>
      )}
    </div>
  );
}

const containerStyle = {
  maxWidth: "600px",
  margin: "0 auto",
  padding: "20px",
  fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
};

const showButtonStyle = {
  padding: "10px 15px",
  border: "1px solid #ccc",
  borderRadius: "5px",
  backgroundColor: "#f9f9f9",
  cursor: "pointer"
};

const slotButtonStyle = (isSelected: boolean) => ({
  padding: "10px 15px",
  border: isSelected ? "2px solid #007bff" : "1px solid #ccc",
  borderRadius: "5px",
  backgroundColor: isSelected ? "#e3f2fd" : "#f9f9f9",
  cursor: "pointer"
});

const signupButtonStyle = {
  padding: "12px 20px",
  backgroundColor: "#007bff",
  color: "white",
  border: "none",
  borderRadius: "5px",
  cursor: "pointer",
  fontSize: "16px",
  width: "100%"
};"
}

