import {
  getAllOrders,
  getOrderById,
  insertOrder,
  updateOrder,
  deleteOrder
} from "../db/orders-table";

export const router = Router();

// Get all orders
router.get("/", (req: Request, res: Response) => {
  try {
    const orders = getAllOrders();
    res.json(orders);
  } catch (error) {
    res.status(500).json({ message: "Failed to fetch orders" });
  }
});

// Get order by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ message: "Invalid order ID" });
    }

    const order = getOrderById(id);
    if (!order) {
      return res.status(404).json({ message: "Order not found" });
    }

    res.json(order);
  } catch (error) {
    res.status(500).json({ message: "Failed to fetch order" });
  }
});

// Create new order
router.post("/", (req: Request, res: Response) => {
  try {
    const { customerId, flavour, size, status } = req.body;

    if (!customerId || !flavour || !size || !status) {
      return res.status(400).json({ message: "Missing required fields" });
    }

    const id = insertOrder(customerId, flavour, size, status);
    const createdOrder = getOrderById(id);

    if (!createdOrder) {
      return res.status(500).json({ message: "Failed to create order" });
    }

    res.status(201).json(createdOrder);
  } catch (error) {
    res.status(500).json({ message: "Failed to create order" });
  }
});

// Update order
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ message: "Invalid order ID" });
    }

    const { customerId, flavour, size, status } = req.body;

    if (!customerId || !flavour || !size || !status) {
      return res.status(400).json({ message: "Missing required fields" });
    }

    const existingOrder = getOrderById(id);
    if (!existingOrder) {
      return res.status(404).json({ message: "Order not found" });
    }

    updateOrder(id, customerId, flavour, size, status);
    const updatedOrder = getOrderById(id);

    if (!updatedOrder) {
      return res.status(500).json({ message: "Failed to update order" });
    }

    res.json(updatedOrder);
  } catch (error) {
    res.status(500).json({ message: "Failed to update order" });
  }
});

