      setLoading(true);
      const response = await fetch('/api/lifeguard-shift-api/shifts');
      if (!response.ok) {
        throw new Error(`Failed to fetch shifts: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleClaimShift = async (shiftId: string) => {
    try {
      const response = await fetch(`/api/lifeguard-shift-api/shifts/${shiftId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ claimedBy: 'current-lifeguard' }),
      });

      if (!response.ok) {
        throw new Error(`Failed to claim shift: ${response.status} ${response.statusText}`);
      }

      // Refresh the shifts list after claiming
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif',
    }}>
      <h1 style={{ textAlign: 'center' }}>Open Shifts</h1>

      {shifts.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No open shifts available.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {shifts.map(shift => (
            <div key={shift.id} style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '15px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
            }}>
              <div>
                <strong>{shift.location}</strong><br />
                {new Date(shift.startTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} - 
                {new Date(shift.endTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
              <button 
                onClick={() => handleClaimShift(shift.id)}
                disabled={!!shift.claimedBy}
                style={{
                  backgroundColor: shift.claimedBy ? '#ccc' : '#007bff',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  padding: '8px 16px',
                  cursor: shift.claimedBy ? 'default' : 'pointer',
                }}
              >
                {shift.claimedBy ? 'Claimed' : 'Claim'}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}"
}

{
  "code": "import { useEffect, useState } from "react";

interface SwapRequest {
  id: string;
  shiftId: string;
  requesterId: string;
  targetUserId: string;
  status: "pending" | "approved" | "rejected";
}

interface Shift {
  id: string;
  date: string;
  startTime: string;
  endTime: string;
  userId: string;
}

export function SwapApprovalQueue() {
  const [swapRequests, setSwapRequests] = useState<SwapRequest[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchSwapRequestsAndShifts() {
      try {
        setLoading(true);
        const [swapRequestsRes, shiftsRes] = await Promise.all([
          fetch("/api/lifeguard-shift-api/swap-requests"),
          fetch("/api/lifeguard-shift-api/shifts"),
        ]);

        if (!swapRequestsRes.ok || !shiftsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const swapRequestsData = await swapRequestsRes.json();
        const shiftsData = await shiftsRes.json();

        setSwapRequests(swapRequestsData);
        setShifts(shiftsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchSwapRequestsAndShifts();
  }, []);

  const handleApprove = async (swapRequestId: string) => {
    try {
      const res = await fetch(
        `/api/lifeguard-shift-api/swap-requests/${swapRequestId}`,
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ status: "approved" }),
        }
      );

      if (!res.ok) {
        throw new Error("Failed to approve swap request");
      }

      // Refresh data
      const [swapRequestsRes, shiftsRes] = await Promise.all([
        fetch("/api/lifeguard-shift-api/swap-requests"),
        fetch("/api/lifeguard-shift-api/shifts"),
      ]);

      if (!swapRequestsRes.ok || !shiftsRes.ok) {
        throw new Error("Failed to refresh data after approval");
      }

      const swapRequestsData = await swapRequestsRes.json();
      const shiftsData = await shiftsRes.json();

      setSwapRequests(swapRequestsData);
      setShifts(shiftsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (swapRequestId: string) => {
    try {
      const res = await fetch(
        `/api/lifeguard-shift-api/swap-requests/${swapRequestId}`,
        {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ status: "rejected" }),
        }
      );

      if (!res.ok) {
        throw new Error("Failed to reject swap request");
      }

      // Refresh data
      const [swapRequestsRes, shiftsRes] = await Promise.all([
        fetch("/api/lifeguard-shift-api/swap-requests"),
        fetch("/api/lifeguard-shift-api/shifts"),
      ]);

      if (!swapRequestsRes.ok || !shiftsRes.ok) {
        throw new Error("Failed to refresh data after rejection");
      }

      const swapRequestsData = await swapRequestsRes.json();
      const shiftsData = await shiftsRes.json();

      setSwapRequests(swapRequestsData);
      setShifts(shiftsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (swapRequests.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No pending swap requests.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Swap Approval Queue</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {swapRequests.map((request) => {
          const shift = shifts.find((s) => s.id === request.shiftId);

          if (!shift) {
            return null;
          }

          return (
            <div
              key={request.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                flexDirection: "column",
                gap: "10px",
              }}
            >
              <div>
                <strong>Shift:</strong> {shift.date} {shift.startTime} - {shift.endTime}
              </div>
              <div>
                <strong>Requester:</strong> {request.requesterId}
              </div>
              <div>
                <strong>Target User:</strong> {request.targetUserId}
              </div>
              <div>
                <strong>Status:</strong> {request.status}
              </div>
              <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
                <button
                  onClick={() => handleApprove(request.id)}
                  style={{
                    backgroundColor: "#4CAF50",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Approve
                </button>
                <button
                  onClick={() => handleReject(request.id)}
                  style={{
                    backgroundColor: "#f44336",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "8px 12px",
                    cursor: "pointer",
                  }}
                >
                  Reject
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}"
}

