import {
  getAllKegs,
  getKegById,
  insertKeg,
  updateKeg,
  deleteKeg
} from "../db/kegs-table";
import {
  getAllBrewers,
  getBrewerById,
  insertBrewer,
  updateBrewer,
  deleteBrewer
} from "../db/brewers-table";
import {
  getAllBatchSpoils,
  getBatchSpoilsById,
  insertBatchSpoils,
  updateBatchSpoils,
  deleteBatchSpoils
} from "../db/batch-spoils-table";

export const router = Router();

// Keg Routes
router.get("/kegs", (req: Request, res: Response) => {
  try {
    const kegs = getAllKegs();
    res.json(kegs);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch kegs" });
  }
});

router.get("/kegs/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const keg = getKegById(id);
    if (!keg) {
      return res.status(404).json({ error: "Keg not found" });
    }
    res.json(keg);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch keg" });
  }
});

router.post("/kegs", (req: Request, res: Response) => {
  try {
    const { stock_quantity, batch_id } = req.body;
    if (typeof stock_quantity !== "number" || typeof batch_id !== "string") {
      return res.status(400).json({ error: "Invalid input data" });
    }
    const id = insertKeg(stock_quantity, batch_id);
    res.status(201).json({ id, stock_quantity, batch_id });
  } catch (error) {
    res.status(500).json({ error: "Failed to create keg" });
  }
});

router.put("/kegs/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { stock_quantity, batch_id } = req.body;
    if (typeof stock_quantity !== "number" || typeof batch_id !== "string") {
      return res.status(400).json({ error: "Invalid input data" });
    }
    updateKeg(id, stock_quantity, batch_id);
    res.json({ id, stock_quantity, batch_id });
  } catch (error) {
    res.status(500).json({ error: "Failed to update keg" });
