interface Keg {
  id: number;
  beerName: string;
  breweryId: number;
  volume: number;
  status: "available" | "empty" | "spoiled";
}

interface Brewer {
  id: number;
  name: string;
}

export function InventoryDashboard() {
  const [kegs, setKegs] = useState<Keg[]>([]);
  const [brewers, setBrewers] = useState<Brewer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newKeg, setNewKeg] = useState({
    beerName: "",
    breweryId: 0,
    volume: 0,
  });

  useEffect(() => {
    fetchKegs();
    fetchBrewers();
  }, []);

  const fetchKegs = async () => {
    try {
      const response = await fetch("/api/inventory-api/kegs");
      if (!response.ok) throw new Error("Failed to fetch kegs");
      const data = await response.json();
      setKegs(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
      setLoading(false);
    }
  };

  const fetchBrewers = async () => {
    try {
      const response = await fetch("/api/inventory-api/brewers");
      if (!response.ok) throw new Error("Failed to fetch brewers");
      const data = await response.json();
      setBrewers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const handleAddKeg = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/inventory-api/kegs", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newKeg),
      });
      if (!response.ok) throw new Error("Failed to add keg");
      setNewKeg({ beerName: "", breweryId: 0, volume: 0 });
      fetchKegs();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  const handleFillKeg = async (id: number) => {
    try {
      const response = await fetch(`/api/inventory-api/kegs/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "available" }),
      });
      if (!response.ok) throw new Error("Failed to fill keg");
      fetchKegs();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={containerStyle}>
      <h1 style={{ textAlign: "center" }}>Keg Inventory Dashboard</h1>

      <div style={sectionStyle}>
        <h2>Current Keg Stock</h2>
        {kegs.length === 0 ? (
          <p style={{ textAlign: "center" }}>No kegs in inventory.</p>
        ) : (
          <div style={kegListStyle}>
            {kegs.map(keg => (
              <div key={keg.id} style={kegCardStyle}>
                <div><strong>{keg.beerName}</strong></div>
                <div>Brewery ID: {keg.breweryId}</div>
                <div>Volume: {keg.volume}L</div>
                <div>Status: {keg.status}</div>
                {keg.status !== "available" && (
                  <button 
                    onClick={() => handleFillKeg(keg.id)}
                    style={fillButtonStyle}
                  >
                    Log Fill
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={sectionStyle}>
        <h2>Add New Keg</h2>
        <form onSubmit={handleAddKeg} style={formStyle}>
          <input
            type="text"
            placeholder="Beer Name"
            value={newKeg.beerName}
            onChange={(e) => setNewKeg({...newKeg, beerName: e.target.value})}
            style={inputStyle}
            required
          />
          <select
            value={newKeg.breweryId}
            onChange={(e) => setNewKeg({...newKeg, breweryId: Number(e.target.value)})}
            style={inputStyle}
            required
          >
            <option value="0">Select Brewery</option>
            {brewers.map(brewer => (
              <option key={brewer.id} value={brewer.id}>{brewer.name}</option>
            ))}
          </select>
          <input
            type="number"
            placeholder="Volume (L)"
            value={newKeg.volume || ""}
            onChange={(e) => setNewKeg({...newKeg, volume: Number(e.target.value)})}
            style={inputStyle}
            required
          />
          <button type="submit" style={submitButtonStyle}>Add Keg</button>
        </form>
      </div>
    </div>
  );
}

