interface Batch {
  id: string;
  batchNumber: string;
  kegId: string;
  status: string;
}

interface Keg {
  id: string;
  name: string;
}

export function SpoiledBatchMark() {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [kegs, setKegs] = useState<Keg[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedKegId, setSelectedKegId] = useState<string>("");
  const [batchNumber, setBatchNumber] = useState<string>("");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [batchesRes, kegsRes] = await Promise.all([
          fetch("/api/inventory-api/kegs"),
          fetch("/api/inventory-api/kegs"),
        ]);

        if (!batchesRes.ok || !kegsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const batchesData = await batchesRes.json();
        const kegsData = await kegsRes.json();

        setBatches(batchesData);
        setKegs(kegsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedKegId || !batchNumber) {
      setError("Please select a keg and enter a batch number");
      return;
    }

    try {
      const response = await fetch("/api/inventory-api/batch-spoils", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          batchNumber,
          kegId: selectedKegId,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to mark batch as spoiled");
      }

      // Refresh data after successful submission
      const [batchesRes, kegsRes] = await Promise.all([
        fetch("/api/inventory-api/kegs"),
        fetch("/api/inventory-api/kegs"),
      ]);

      if (!batchesRes.ok || !kegsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const batchesData = await batchesRes.json();
      const kegsData = await kegsRes.json();

      setBatches(batchesData);
      setKegs(kegsData);
      setBatchNumber("");
      setSelectedKegId("");
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "600px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Mark Batch as Spoiled</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "20px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="kegSelect" style={{ display: "block", marginBottom: "5px" }}>
            Select Keg:
          </label>
          <select
            id="kegSelect"
            value={selectedKegId}
            onChange={(e) => setSelectedKegId(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Choose a keg</option>
            {kegs.map((keg) => (
              <option key={keg.id} value={keg.id}>
                {keg.name}
              </option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="batchNumber" style={{ display: "block", marginBottom: "5px" }}>
            Batch Number:
          </label>
          <input
            id="batchNumber"
            type="text"
            value={batchNumber}
            onChange={(e) => setBatchNumber(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            placeholder="Enter batch number"
          />
        </div>

        <button
          type="submit"
          style={{
            backgroundColor: "#dc3545",
            color: "white",
            border: "none",
            padding: "10px 15px",
            borderRadius: "4px",
            cursor: "pointer",
            width: "100%",
          }}
        >
          Mark as Spoiled
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Current Batches</h2>
      {batches.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No batches found.</p>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
          <thead>
            <tr style={{ borderBottom: "1px solid #ddd" }}>
              <th style={{ padding: "10px", textAlign: "left" }}>Batch Number</th>
              <th style={{ padding: "10px", textAlign: "left" }}>Keg</th>
              <th style={{ padding: "10px", textAlign: "left" }}>Status</th>
            </tr>
          </thead>
          <tbody>
            {batches.map((batch) => (
              <tr key={batch.id} style={{ borderBottom: "1px solid #eee" }}>
                <td style={{ padding: "10px" }}>{batch.batchNumber}</td>
                <td style={{ padding: "10px" }}>
                  {kegs.find((k) => k.id === batch.kegId)?.name || "Unknown Keg"}
                </td>
                <td style={{ padding: "10px" }}>{batch.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}"
}

