);

interface MachineRow {
  id: number;
  status: string;
  last_broken_timestamp: number | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS machines (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    status TEXT NOT NULL,
    last_broken_timestamp INTEGER
  )
`;

db.exec(createTableSql);

export function getAllMachines(): MachineRow[] {
  const stmt = db.prepare(`SELECT * FROM machines`);
  return stmt.all() as unknown as MachineRow[];
}

export function getMachineById(id: number): MachineRow | undefined {
  const stmt = db.prepare(`SELECT * FROM machines WHERE id = ?`);
  return stmt.get(id) as unknown as MachineRow | undefined;
}

export function insertMachine(
  status: string,
  lastBrokenTimestamp: number | null
): number {
  const stmt = db.prepare(
    `INSERT INTO machines (status, last_broken_timestamp) VALUES (?, ?)`
  );
  const result = stmt.run(status, lastBrokenTimestamp);
  return Number(result.lastInsertRowid);
}

