  id: number,
  status: string,
  lastBrokenTimestamp: number | null
): void {
  const stmt = db.prepare(
    `UPDATE machines SET status = ?, last_broken_timestamp = ? WHERE id = ?`
  );
  stmt.run(status, lastBrokenTimestamp, id);
}

