  const [machines, setMachines] = useState<Machine[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchMachines();
  }, []);

  const fetchMachines = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/machine-tracker-api/machines");
      if (!response.ok) {
        throw new Error(`Failed to fetch machines: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setMachines(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const updateMachineStatus = async (id: number, status: Machine["status"]) => {
    try {
      const response = await fetch(`/api/machine-tracker-api/machines/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status }),
      });
      if (!response.ok) {
        throw new Error(`Failed to update machine: ${response.status} ${response.statusText}`);
