import {
  db,
  deleteAttendance,
  getAllAttendance,
  getAttendanceById,
  insertAttendance,
  updateAttendance
} from "../db/attendance-table";

export const router = Router();

// Get all attendance records
router.get("/", (req: Request, res: Response) => {
  try {
    const attendance = getAllAttendance();
    res.json(attendance);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch attendance records" });
  }
});

// Get a specific attendance record by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const attendance = getAttendanceById(id);
    if (!attendance) {
      return res.status(404).json({ error: "Attendance record not found" });
    }

    res.json(attendance);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch attendance record" });
  }
});

// Create a new attendance record
router.post("/", (req: Request, res: Response) => {
  try {
    const { singerId, date, status } = req.body;

    if (!singerId || !date || !status) {
      return res.status(400).json({ error: "Missing required fields: singerId, date, status" });
    }

    if (status !== "present" && status !== "absent") {
      return res.status(400).json({ error: "Status must be either 'present' or 'absent'" });
    }

    const newId = insertAttendance(singerId, date, status);
    const newRecord = getAttendanceById(newId);

    if (!newRecord) {
      return res.status(500).json({ error: "Failed to create attendance record" });
    }

    res.status(201).json(newRecord);
  } catch (error) {
    res.status(500).json({ error: "Failed to create attendance record" });
  }
});

// Update an existing attendance record
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { singerId, date, status } = req.body;

    if (!singerId || !date || !status) {
      return res.status(400).json({ error: "Missing required fields: singerId, date, status" });
    }

    if (status !== "present" && status !== "absent") {
      return res.status(400).json({ error: "Status must be either 'present' or 'absent'" });
    }

    const existingRecord = getAttendanceById(id);
    if (!existingRecord) {
      return res.status(404).json({ error: "Attendance record not found" });
    }

    updateAttendance(id, singerId, date, status);
    const updatedRecord = getAttendanceById(id);

    if (!updatedRecord) {
      return res.status(500).json({ error: "Failed to update attendance record" });
    }

    res.json(updatedRecord);
