    date: "",
    status: "present" as "present" | "absent"
  });

  useEffect(() => {
    fetchAttendanceRecords();
  }, []);

  const fetchAttendanceRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/attendance-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setNewRecord(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/attendance-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newRecord)
      });
      if (!response.ok) {
        throw new Error(`Failed to create record: ${response.status} ${response.statusText}`);
      }
      // Reset form
      setNewRecord({
        singerName: "",
        date: "",
        status: "present"
      });
      // Refresh data
      await fetchAttendanceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const updateStatus = async (id: string, status: "present" | "absent") => {
    try {
      const response = await fetch(`/api/attendance-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status })
      });
      if (!response.ok) {
        throw new Error(`Failed to update record: ${response.status} ${response.statusText}`);
      }
      await fetchAttendanceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const deleteRecord = async (id: string) => {
    try {
      const response = await fetch(`/api/attendance-api/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`Failed to delete record: ${response.status} ${response.statusText}`);
