      <h2>Attendance Records</h2>
      {records.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {records.map(record => (
            <div key={record.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <strong>{record.singerName}</strong> - {record.date}
                <br />
                Status: <span style={{ fontWeight: "bold" }}>{record.status}</span>
              </div>
              <div style={{ display: "flex", gap: "5px" }}>
                <button 
                  onClick={() => updateStatus(record.id, "present")}
                  style={{ backgroundColor: record.status === "present" ? "green" : "#28a745", color: "white", padding: "5px 10px", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Present
                </button>
                <button 
                  onClick={() => updateStatus(record.id, "absent")}
                  style={{ backgroundColor: record.status === "absent" ? "red" : "#dc3545", color: "white", padding: "5px 10px", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Absent
