    "code": "import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

const createTableSql = `
  CREATE TABLE IF NOT EXISTS aging_batches (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    cheesemaker_id INTEGER NOT NULL,
    date_started TEXT NOT NULL,
    date_finished TEXT,
    sale_approved BOOLEAN DEFAULT FALSE
  )
`;

db.exec(createTableSql);

export interface AgingBatchRow {
  id: number;
  cheesemaker_id: number;
  date_started: string;
  date_finished: string | null;
  sale_approved: boolean;
}

export function getAllAgingBatches(): AgingBatchRow[] {
  const stmt = db.prepare(`SELECT * FROM aging_batches`);
  return stmt.all() as unknown as AgingBatchRow[];
}

export function getAgingBatchById(id: number): AgingBatchRow | undefined {
  const stmt = db.prepare(`SELECT * FROM aging_batches WHERE id = ?`);
  return stmt.get(id) as unknown as AgingBatchRow | undefined;
}

export function insertAgingBatch(
  cheesemakerId: number,
  dateStarted: string,
  dateFinished: string | null,
  saleApproved: boolean
): number {
  const stmt = db.prepare(
    `INSERT INTO aging_batches (cheesemaker_id, date_started, date_finished, sale_approved) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(cheesemakerId, dateStarted, dateFinished, saleApproved);
  return Number(result.lastInsertRowid);
}

export function updateAgingBatch(
  id: number,
  cheesemakerId: number,
  dateStarted: string,
  dateFinished: string | null,
  saleApproved: boolean
): void {
  const stmt = db.prepare(
    `UPDATE aging_batches SET cheesemaker_id = ?, date_started = ?, date_finished = ?, sale_approved = ? WHERE id = ?`
  );
  stmt.run(cheesemakerId, dateStarted, dateFinished, saleApproved, id);
}

export function deleteAgingBatch(id: number): void {
  const stmt = db.prepare(`DELETE FROM aging_batches WHERE id = ?`);
  stmt.run(id);
}

