import {
  createBooking,
  deleteBooking,
  getAllBookings,
  getBookingById,
  updateBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  try {
    const bookings = getAllBookings();
    res.json(bookings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    res.json(booking);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch booking" });
  }
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  try {
    const { guestId, roomId, checkInDate, checkOutDate, staffOverride } = req.body;

    // Validate required fields
    if (!guestId || !roomId || !checkInDate || !checkOutDate) {
      return res.status(400).json({
        error: "Missing required fields: guestId, roomId, checkInDate, checkOutDate"
      });
    }

    const newBooking = createBooking(
      Number(guestId),
      Number(roomId),
      checkInDate,
      checkOutDate,
      Boolean(staffOverride)
    );

    res.status(201).json(newBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { guestId, roomId, checkInDate, checkOutDate, staffOverride } = req.body;

    // Validate required fields
    if (isNaN(id) || !guestId || !roomId || !checkInDate || !checkOutDate) {
      return res.status(400).json({
        error: "Missing required fields: id, guestId, roomId, checkInDate, checkOutDate"
      });
    }

    updateBooking(
      id,
      Number(guestId),
      Number(roomId),
      checkInDate,
      checkOutDate,
      Boolean(staffOverride)
    );

    res.json({ message: "Booking updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update booking" });
  }
});

// Delete a booking
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    deleteBooking(id);
    res.json({ message: "Booking deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete booking" });
  }
