export function BookingForm() {
  const [selectedDate, setSelectedDate] = useState<string>("");
  const [selectedRoom, setSelectedRoom] = useState<string>("");
  const [rooms, setRooms] = useState<Array<{ id: string; name: string }>>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<boolean>(false);

  useEffect(() => {
    const fetchRooms = async () => {
      try {
        const response = await fetch("/api/bookings-api/");
        if (!response.ok) {
          throw new Error(`Failed to fetch rooms: ${response.status}`);
        }
        const data = await response.json();
        setRooms(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchRooms();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDate || !selectedRoom) return;

    try {
      const response = await fetch("/api/bookings-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          date: selectedDate,
          roomId: selectedRoom,
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book: ${response.status}`);
      }

      setSuccess(true);
      setSelectedDate("");
      setSelectedRoom("");

      // Refresh rooms list after booking
      const refreshResponse = await fetch("/api/bookings-api/");
      if (refreshResponse.ok) {
        const data = await refreshResponse.json();
        setRooms(data);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  return (
    <div style={containerStyle}>
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>Book a Bed</h1>

      {error && <div style={{ color: "red", textAlign: "center", marginBottom: "20px" }}>{error}</div>}

      {success && (
        <div style={{ color: "green", textAlign: "center", marginBottom: "20px" }}>
          Booking successful!
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="date" style={{ display: "block", marginBottom: "5px" }}>
            Select Date:
          </label>
          <input
            type="date"
            id="date"
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="room" style={{ display: "block", marginBottom: "5px" }}>
            Select Room:
          </label>
          <select
            id="room"
            value={selectedRoom}
            onChange={(e) => setSelectedRoom(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          >
            <option value="">Choose a room</option>
            {rooms.map((room) => (
              <option key={room.id} value={room.id}>
                {room.name}
              </option>
            ))}
          </select>
        </div>

        <button
          type="submit"
          style={{
            padding: "10px 15px",
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
            fontSize: "16px",
          }}
        >
          Book Bed
        </button>
      </form>

      {rooms.length === 0 && !error && (
        <p style={{ textAlign: "center", marginTop: "20px" }}>No rooms available.</p>
      )}
    </div>
  );
}

