  "code": "import { useEffect, useState } from "react";

interface Booking {
  id: string;
  bedId: string;
  guestName: string;
  checkInDate: string;
  checkOutDate: string;
}

export function RoomStatusBoard() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (bookings.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No bookings found for today.</div>;
  }

  // Group bookings by bed ID
  const beds = Array.from(new Set(bookings.map(b => b.bedId)));

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Room Status Board</h1>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
        {beds.map(bedId => {
          const bedBookings = bookings.filter(b => b.bedId === bedId);
          const isOccupied = bedBookings.length > 0;

          return (
            <div 
              key={bedId} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                minWidth: '200px', 
                flex: '1 1 200px'
              }}
            >
              <h3 style={{ margin: '0 0 10px 0', textAlign: 'center' }}>Bed {bedId}</h3>
              {isOccupied ? (
                <ul style={{ margin: '0', padding: '0' }}>
                  {bedBookings.map(booking => (
                    <li key={booking.id} style={{ marginBottom: '5px' }}>
                      <strong>{booking.guestName}</strong><br />
                      <small>{booking.checkInDate} to {booking.checkOutDate}</small>
                    </li>
                  ))}
                </ul>
              ) : (
                <p style={{ textAlign: 'center', color: '#666' }}>Available</p>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}"
}

