export function insertPhoto(
  itemId: number,
  url: string,
  caption?: string
): number {
  const stmt = db.prepare(
    `INSERT INTO photos (itemId, url, caption) VALUES (?, ?, ?)`
  );
  const result = stmt.run(itemId, url, caption);
  return Number(result.lastInsertRowid);
}

export function updatePhoto(
  id: number,
  itemId: number,
  url: string,
  caption?: string
): void {
  const stmt = db.prepare(
    `UPDATE photos SET itemId = ?, url = ?, caption = ? WHERE id = ?`
  );
  stmt.run(itemId, url, caption, id);
}

export function deletePhoto(id: number): void {
  const stmt = db.prepare(`DELETE FROM photos WHERE id = ?`);
  stmt.run(id);
}

