      <h1 style={{ textAlign: "center" }}>Item Editor</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="text"
            name="name"
            placeholder="Item Name"
            value={formData.name}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <textarea
            name="description"
            placeholder="Description"
            value={formData.description}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box", height: "80px" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <input
            type="number"
            name="quantity"
            placeholder="Quantity"
            value={formData.quantity}
            onChange={handleChange}
            min="1"
            style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
            required
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          {editingId ? "Update Item" : "Add Item"}
        </button>
      </form>

      <div>
        <h2>Inventory Items</h2>
        {items.length === 0 ? (
          <p style={{ textAlign: "center", color: "#666" }}>No items found.</p>
        ) : (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
            {items.map(item => (
              <div 
                key={item.id} 
                style={{ 
                  border: "1px solid #ddd", 
                  borderRadius: "8px", 
                  padding: "15px", 
                  width: "200px", 
                  boxSizing: "border-box" 
                }}
              >
                <h3>{item.name}</h3>
                <p>{item.description}</p>
                <p>Qty: {item.quantity}</p>
                <div style={{ marginTop: "10px", display: "flex", gap: "5px" }}>
                  <button 
                    onClick={() => handleEdit(item)}
                    style={{ 
                      backgroundColor: "#ffc107", 
                      color: "black", 
                      border: "none", 
                      padding: "5px 10px", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(item.id)}
                    style={{ 
                      backgroundColor: "#dc3545", 
                      color: "white", 
                      border: "none", 
                      padding: "5px 10px", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
