  "code": "import { useState, useRef } from "react";

export function PhotoUploadWidget() {
  const [photo, setPhoto] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setPhoto(file);
      setPreviewUrl(URL.createObjectURL(file));
      setError(null);
    }
  };

  const handleUpload = async () => {
    if (!photo) return;

    setUploading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append("photo", photo);

      const response = await fetch("/api/photo-storage-service/photos", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        throw new Error(`Upload failed: ${response.status}`);
      }

      // Reset form after successful upload
      setPhoto(null);
      setPreviewUrl(null);
      if (fileInputRef.current) {
        fileInputRef.current.value = "";
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div style={{
      maxWidth: 600,
      margin: "0 auto",
      padding: 20,
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h2>Photo Upload</h2>

      <div style={{ marginBottom: 20 }}>
        <input
          type="file"
          accept="image/*"
          onChange={handleFileChange}
          ref={fileInputRef}
          style={{ display: "block", width: "100%" }}
        />
      </div>

      {previewUrl && (
        <div style={{ marginBottom: 20 }}>
          <img 
            src={previewUrl} 
            alt="Preview" 
            style={{ maxWidth: "100%", borderRadius: 8 }}
          />
        </div>
      )}

      <button
        onClick={handleUpload}
        disabled={!photo || uploading}
        style={{
          backgroundColor: "#007AFF",
          color: "white",
          border: "none",
          borderRadius: 8,
          padding: "12px 20px",
          fontSize: 16,
          cursor: photo && !uploading ? "pointer" : "default",
          opacity: photo && !uploading ? 1 : 0.5,
        }}
      >
        {uploading ? "Uploading..." : "Upload Photo"}
      </button>

      {error && (
        <div style={{ marginTop: 20, color: "#FF3B30", padding: 10, backgroundColor: "#FFEBEE", borderRadius: 8 }}>
          {error}
        </div>
      )}
    </div>
  );
}"
}

