import { insertWateringEvent, getAllWateringEvents } from "../db/watering-events-table";
import { getPlantById } from "../db/plants-table";

export const router = Router();

// Record a watering event and compute the next scheduled watering
router.post("/watering-events", (req: Request, res: Response) => {
  const { plantId, timestamp, operatorId } = req.body;

  // Validate required fields
  if (!plantId || !timestamp || !operatorId) {
    return res.status(400).json({ error: "Missing required fields: plantId, timestamp, operatorId" });
  }

  // Convert plantId and operatorId to numbers
  const plantIdNum = Number(plantId);
  const operatorIdNum = Number(operatorId);

  // Validate numeric fields
  if (isNaN(plantIdNum) || isNaN(operatorIdNum)) {
    return res.status(400).json({ error: "plantId and operatorId must be numbers" });
  }

  // Check if plant exists
  const plant = getPlantById(plantIdNum);
  if (!plant) {
    return res.status(404).json({ error: "Plant not found" });
  }

  // Insert the watering event
  const eventId = insertWateringEvent(plantIdNum, timestamp, operatorIdNum);

  // Compute next scheduled watering (for now, just return the event)
  // In a real implementation, this would calculate based on plant's watering interval
  const wateringEvents = getAllWateringEvents();
  const latestEvent = wateringEvents
    .filter(event => event.plant_id === plantIdNum)
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())[0];

  // Return the created event
  return res.status(201).json({
    id: eventId,
    plant_id: plantIdNum,
    timestamp,
    operator_id: operatorIdNum,
    next_watering: latestEvent ? new Date(latestEvent.timestamp).setDate(new Date(latestEvent.timestamp).getDate() + 7) : null
  });
});"
}

