import { router as mileageApiRouter } from "../routes/mileage-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check tax year for requests to the mileage API routes
  if (!req.path.startsWith("/api/mileage")) {
    next();
    return;
  }

  // For POST, PUT, DELETE requests to mileage API, check tax year
  if ((req.method === "POST" || req.method === "PUT" || req.method === "DELETE") && 
      req.path.startsWith("/api/mileage")) {
    // Check if the request has a body with a taxYear property
    if (req.body && typeof req.body.taxYear !== "undefined") {
      const currentTaxYear = new Date().getFullYear();
      const entryTaxYear = parseInt(req.body.taxYear, 10);

      if (isNaN(entryTaxYear) || entryTaxYear !== currentTaxYear) {
        res.status(400).json({
          error: `Entry tax year ${entryTaxYear} does not match current tax year ${currentTaxYear}`
        });
        return;
      }
    }
  }

  next();
}"
}

