{
  "code": "import { useEffect, useState } from "react";

interface MileageEntry {
  id: number;
  date: string;
  miles: number;
  description: string;
}

interface SummaryItem {
  period: string;
  totalMiles: number;
}

export function TaxDeductionSummary() {
  const [mileageEntries, setMileageEntries] = useState<MileageEntry[]>([]);
  const [summary, setSummary] = useState<SummaryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchMileageData = async () => {
      try {
        const response = await fetch("/api/mileage-api/");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setMileageEntries(data);

        // Aggregate by month/quarter/year
        const summaryMap = new Map<string, number>();

        data.forEach((entry: MileageEntry) => {
          const date = new Date(entry.date);
          const year = date.getFullYear();

          // Monthly aggregation
          const monthKey = `${year}-${String(date.getMonth() + 1).padStart(2, '0')}`;
          summaryMap.set(
            monthKey,
            (summaryMap.get(monthKey) || 0) + entry.miles
          );

          // Quarterly aggregation
          const quarter = Math.floor(date.getMonth() / 3) + 1;
          const quarterKey = `${year}-Q${quarter}`;
          summaryMap.set(
            quarterKey,
            (summaryMap.get(quarterKey) || 0) + entry.miles
          );

          // Yearly aggregation
          const yearKey = `${year}`;
          summaryMap.set(
            yearKey,
            (summaryMap.get(yearKey) || 0) + entry.miles
          );
        });

        const sortedSummary = Array.from(summaryMap.entries())
          .map(([period, totalMiles]) => ({ period, totalMiles }))
          .sort((a, b) => a.period.localeCompare(b.period));

        setSummary(sortedSummary);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchMileageData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (summary.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No mileage data available.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Tax Deduction Summary</h1>
      <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
        <thead>
          <tr style={{ borderBottom: "1px solid #ccc" }}>
            <th style={{ padding: "10px", textAlign: "left" }}>Period</th>
            <th style={{ padding: "10px", textAlign: "left" }}>Total Miles</th>
          </tr>
        </thead>
        <tbody>
          {summary.map((item, index) => (
            <tr key={index} style={{ borderBottom: "1px solid #eee" }}>
              <td style={{ padding: "10px" }}>{item.period}</td>
              <td style={{ padding: "10px" }}>{item.totalMiles}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}"
}

