  "code": "import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect DELETE requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if the request is for a route that requires supervisor access
  // For this implementation, we'll assume all DELETE requests require supervisor access
  // In a real application, you might want to check specific routes

  // Get the user role from the request (assuming it's set by a previous middleware)
  const userRole = req.headers["x-user-role"] as string | undefined;

  // If no role is provided, reject the request
  if (!userRole) {
    res.status(403).json({ error: "Access denied: Supervisor role required" });
    return;
  }

  // Check if the user has supervisor role
  if (userRole.toLowerCase() !== "supervisor") {
    res.status(403).json({ error: "Access denied: Supervisor role required" });
    return;
  }

  // If user is supervisor, allow the request to proceed
  next();
}"
}

