  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTrucks();
  }, []);

  const fetchTrucks = async () => {
    try {
      const response = await fetch("/api/routes-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch trucks: ${response.status}`);
