import { db, deleteRoute, getAllRoutes, getRouteById, insertRoute, updateRoute } from "../db/routes-table";

export const router = Router();

// Middleware to check if user is supervisor
const supervisorGuard = (req: Request, res: Response, next: () => void) => {
  // For now, we'll just allow all requests
  // In a real implementation, this would check user permissions
  next();
};

// GET /routes - Get all routes
router.get("/", (req: Request, res: Response) => {
