    res.json(routes);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch routes" });
  }
});

// GET /routes/:id - Get a specific route by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const route = getRouteById(id);

    if (!route) {
      return res.status(404).json({ error: "Route not found" });
    }

    res.json(route);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch route" });
  }
});

// POST /routes - Create a new route
router.post("/", (req: Request, res: Response) => {
  try {
    const { name, description, distance, duration } = req.body;

    if (!name || !description || !distance || !duration) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newRouteId = insertRoute({ name, description, distance, duration });
    const newRoute = getRouteById(newRouteId);

    if (!newRoute) {
      return res.status(500).json({ error: "Failed to create route" });
    }

    res.status(201).json(newRoute);
  } catch (error) {
    res.status(500).json({ error: "Failed to create route" });
  }
});

// PUT /routes/:id - Update a route
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { name, description, distance, duration } = req.body;

    if (!name || !description || !distance || !duration) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const updated = updateRoute(id, { name, description, distance, duration });

    if (!updated) {
      return res.status(404).json({ error: "Route not found" });
    }

    const updatedRoute = getRouteById(id);
    res.json(updatedRoute);
  } catch (error) {
    res.status(500).json({ error: "Failed to update route" });
  }
});

// DELETE /routes/:id - Delete a route
router.delete("/:id", supervisorGuard, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const deleted = deleteRoute(id);

    if (!deleted) {
      return res.status(404).json({ error: "Route not found" });
    }

    res.json({ message: "Route deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete route" });
  }
});"
