  }

  const newStudentId = Number(studentId);
  if (isNaN(newStudentId)) {
    return res.status(400).json({ error: "Invalid student ID" });
  }

  const checkoutId = insertCheckout(newStudentId, isbn, dueDate);
  res.status(201).json({ id: checkoutId });
