    "code": "import { Router, type Request, type Response } from "express";
import {
  db,
  deleteTour,
  getAllTours,
  getTourById,
  insertTour,
  updateTour
} from "../db/tours-table";

export const router = Router();

// GET /tours - Get all tours
router.get("/tours", (req: Request, res: Response) => {
  try {
    const tours = getAllTours();
    res.json(tours);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch tours" });
  }
});

// GET /tours/:id - Get a specific tour by ID
router.get("/tours/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid tour ID" });
    }

    const tour = getTourById(id);
    if (!tour) {
      return res.status(404).json({ error: "Tour not found" });
    }

    res.json(tour);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch tour" });
  }
});

// POST /tours - Create a new tour
router.post("/tours", (req: Request, res: Response) => {
  try {
    const { docentName, startTime, endTime, maxParticipants } = req.body;

    if (!docentName || !startTime || !endTime || maxParticipants === undefined) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newTourId = insertTour({
      docentName,
      startTime,
      endTime,
      maxParticipants
    });

    const createdTour = getTourById(newTourId);
    if (!createdTour) {
      return res.status(500).json({ error: "Failed to create tour" });
    }

    res.status(201).json(createdTour);
  } catch (error) {
    res.status(500).json({ error: "Failed to create tour" });
  }
});

// PUT /tours/:id - Update an existing tour
router.put("/tours/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid tour ID" });
    }

    const { docentName, startTime, endTime, maxParticipants } = req.body;

    const tourExists = getTourById(id);
    if (!tourExists) {
      return res.status(404).json({ error: "Tour not found" });
    }

    const updatedRows = updateTour(id, {
      docentName,
      startTime,
      endTime,
      maxParticipants
    });

    if (updatedRows === 0) {
      return res.status(404).json({ error: "Tour not found" });
    }

    const updatedTour = getTourById(id);
    if (!updatedTour) {
      return res.status(500).json({ error: "Failed to update tour" });
    }

    res.json(updatedTour);
  } catch (error) {
    res.status(500).json({ error: "Failed to update tour" });
  }
});

// DELETE /tours/:id - Delete a tour (supervisor-only)
router.delete("/tours/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid tour ID" });
    }

    const deletedRows = deleteTour(id);
    if (deletedRows === 0) {
      return res.status(404).json({ error: "Tour not found" });
    }

    res.json({ message: "Tour deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete tour" });
  }
});"
}

{
  "code": "import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as toursApiRouter } from "../routes/tours-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests to the tours API routes
  if (req.method !== "DELETE" || !req.path.startsWith("/api/tours")) {
    next();
    return;
  }

  // Check if the user is a supervisor
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd want proper JWT verification)
  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Reconstruct the signature for comparison
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // Parse payload to check role (simplified)
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString()
    );

    // If user is a supervisor, reject deletion of their own record
    if (decodedPayload.role === "supervisor" && req.params.id === decodedPayload.id) {
      res.status(403).json({ error: "Supervisors cannot delete their own records" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}"
}

