  email: string;
  role: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS supervisors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    role TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllSupervisors(): Supervisor[] {
  const stmt = db.prepare("SELECT * FROM supervisors");
  return stmt.all() as unknown as Supervisor[];
}

export function getSupervisorById(id: number): Supervisor | undefined {
  const stmt = db.prepare("SELECT * FROM supervisors WHERE id = ?");
  return stmt.get(id) as unknown as Supervisor | undefined;
}

export function insertSupervisor(supervisor: Omit<Supervisor, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO supervisors (name, email, role) VALUES (?, ?, ?)"
  );
  const result = stmt.run(supervisor.name, supervisor.email, supervisor.role);
  return Number(result.lastInsertRowid);
}

export function updateSupervisor(
  id: number,
  supervisor: Partial<Omit<Supervisor, "id">>
): boolean {
  const fields = [];
  const values = [];

  if (supervisor.name !== undefined) {
    fields.push("name = ?");
    values.push(supervisor.name);
  }

  if (supervisor.email !== undefined) {
    fields.push("email = ?");
    values.push(supervisor.email);
  }

  if (supervisor.role !== undefined) {
    fields.push("role = ?");
    values.push(supervisor.role);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE supervisors SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);
  return true;
}

export function deleteSupervisor(id: number): boolean {
  const stmt = db.prepare("DELETE FROM supervisors WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

