import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests to the /supervisors endpoint
  if (req.method !== "DELETE" || !req.path.startsWith("/supervisors")) {
    next();
    return;
  }

  // Check if user is supervisor
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd want proper JWT verification)
  try {
    const [payload] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64");

    // For demo purposes, we'll just check if it's a valid base64 string
    // In a real implementation, you'd decode and verify properly
    const isValid = Buffer.from(expectedSignature, "base64").length > 0;

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Mock supervisor check - in a real app, you'd decode the token
  // and check if the user has supervisor role
  const isSupervisor = true; // This would come from token payload in a real app

  if (!isSupervisor) {
    res.status(403).json({ error: "Forbidden: Supervisor access required" });
    return;
  }

  next();
}"
}

