    try {
      const response = await fetch("/api/donations-api/");
      if (!response.ok) throw new Error("Failed to fetch donations");
      const data = await response.json();
      setDonations(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
      setLoading(false);
    }
  };

