import { insertCheckin, getCheckinById, updateCheckin, deleteCheckin } from "../db/checkins-table";
import { insertAuditTrail } from "../db/audit-trail-table";

export const router = Router();

// POST /check-ins - Record a new check-in event
router.post("/", (req: Request, res: Response) => {
  const { memberId, dogName, checkInTime } = req.body;

  // Validate required fields
  if (!memberId || !dogName || !checkInTime) {
    return res.status(400).json({ error: "Member ID, dog name, and check-in time are required." });
  }

  try {
    const newCheckinId = insertCheckin(
      Number(memberId),
      dogName,
      checkInTime
    );

    // Log audit trail
    insertAuditTrail(Number(memberId), "check-in", checkInTime);

    return res.status(201).json({ id: newCheckinId, memberId, dogName, checkInTime });
  } catch (error) {
    return res.status(500).json({ error: "Failed to record check-in." });
  }
});

// GET /check-ins/:id - Retrieve a specific check-in by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid check-in ID." });
  }

  const checkin = getCheckinById(id);

  if (!checkin) {
    return res.status(404).json({ error: "Check-in not found." });
  }

  return res.json(checkin);
});

// PUT /check-ins/:id - Update a check-in event
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { memberId, dogName, checkInTime, checkOutTime } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid check-in ID." });
  }

  if (!memberId || !dogName || !checkInTime) {
    return res.status(400).json({ error: "Member ID, dog name, and check-in time are required." });
  }

  try {
    updateCheckin(id, Number(memberId), dogName, checkInTime, checkOutTime);
    return res.json({ id, memberId, dogName, checkInTime, checkOutTime });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update check-in." });
  }
});

// DELETE /check-ins/:id - Remove a check-in event
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid check-in ID." });
  }

  try {
    deleteCheckin(id);
    return res.json({ message: "Check-in deleted successfully." });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete check-in." });
  }
});"
