router.get("/", (req: Request, res: Response) => {
  try {
    const harvests = getAllHarvests();
    res.json(harvests);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch harvests" });
  }
});

// Get a specific harvest by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid harvest ID" });
    }

    const harvest = getHarvestById(id);
    if (!harvest) {
      return res.status(404).json({ error: "Harvest not found" });
    }

    res.json(harvest);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch harvest" });
  }
});

