  try {
    const { plotId, quantity, staffMemberId } = req.body;

    if (typeof plotId !== "number" || typeof quantity !== "number" || typeof staffMemberId !== "number") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const newId = insertHarvest(plotId, quantity, staffMemberId);
    const newHarvest = getHarvestById(newId);

    if (!newHarvest) {
