  insertAttendanceRecord(2, "2023-05-01", "absent");
  insertAttendanceRecord(3, "2023-05-01", "late");
  insertAttendanceRecord(4, "2023-05-02", "present");
  insertAttendanceRecord(5, "2023-05-02", "present");
}"
}

