  // Validate presence_status
  const validStatuses = ["present", "absent", "late"];
  if (!validStatuses.includes(presence_status)) {
    return res.status(400).json({ error: "Invalid presence_status. Must be 'present', 'absent', or 'late'" });
  }

  try {
    const newId = insertAttendanceRecord(member_id, date, presence_status);
    const newRecord = getAttendanceRecordById(newId);

    if (!newRecord) {
      return res.status(500).json({ error: "Failed to retrieve created record" });
    }

    res.status(201).json(newRecord);
  } catch (error) {
    res.status(500).json({ error: "Failed to create attendance record" });
  }
