export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Only check requests to /supervisors/
  if (!req.path.startsWith("/supervisors/")) {
    next();
    return;
  }

  // Check if the user is trying to delete their own record
  const userId = req.params.id;
  const authenticatedUserId = req.user?.id;

  if (userId && authenticatedUserId && userId === authenticatedUserId) {
    res.status(403).json({
      error: "Supervisors cannot delete their own records",
    });
    return;
  }

  next();
}"
