export const db = new DatabaseSync(
  "/tmp/studio-equipment-checkout.db"
);

interface Checkout {
  id: number;
  artistId: number;
  toolId: number;
  checkoutTimestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS checkouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    artistId INTEGER NOT NULL,
    toolId INTEGER NOT NULL,
    checkoutTimestamp TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllCheckouts(): Checkout[] {
  const stmt = db.prepare(`SELECT * FROM checkouts`);
  return stmt.all() as unknown as Checkout[];
}

export function getCheckoutById(id: number): Checkout | undefined {
  const stmt = db.prepare(
    `SELECT * FROM checkouts WHERE id = ?`
  );
  return stmt.get(id) as unknown as Checkout | undefined;
}

export function insertCheckout(
  artistId: number,
  toolId: number,
  checkoutTimestamp: string
): number {
  const stmt = db.prepare(
    `INSERT INTO checkouts (artistId, toolId, checkoutTimestamp) VALUES (?, ?, ?)`
  );
  const result = stmt.run(artistId, toolId, checkoutTimestamp);
  return Number(result.lastInsertRowid);
}

export function updateCheckout(
  id: number,
  artistId: number,
  toolId: number,
  checkoutTimestamp: string
): void {
  const stmt = db.prepare(
    `UPDATE checkouts SET artistId = ?, toolId = ?, checkoutTimestamp = ? WHERE id = ?`
  );
  stmt.run(artistId, toolId, checkoutTimestamp, id);
}

export function deleteCheckout(id: number): void {
