  const { artistId, toolId, checkoutTimestamp } = req.body;

  if (!artistId || !toolId || !checkoutTimestamp) {
    return res.status(400).json({ error: "Missing required fields: artistId, toolId, checkoutTimestamp" });
  }

  const id = insertCheckout(artistId, toolId, checkoutTimestamp);

  res.status(201).json({ id });
});

// Update an existing checkout
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { artistId, toolId, checkoutTimestamp } = req.body;

  if (isNaN(id)) {
