export const db = new DatabaseSync("./range-bookings.db");

interface BookingRow {
  id: number;
  member_id: number;
  lane_id: number;
  start_time: string;
  end_time: string;
  is_supervisor: boolean;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS bookings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER NOT NULL,
    lane_id INTEGER NOT NULL,
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL,
    is_supervisor BOOLEAN NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllBookings(): BookingRow[] {
  const stmt = db.prepare("SELECT * FROM bookings");
  return stmt.all() as unknown as BookingRow[];
}

export function getBookingById(id: number): BookingRow | undefined {
  const stmt = db.prepare("SELECT * FROM bookings WHERE id = ?");
  return stmt.get(id) as unknown as BookingRow | undefined;
}

export function insertBooking(
  member_id: number,
  lane_id: number,
  start_time: string,
  end_time: string,
  is_supervisor: boolean
): number {
  const stmt = db.prepare(
    "INSERT INTO bookings (member_id, lane_id, start_time, end_time, is_supervisor) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(member_id, lane_id, start_time, end_time, is_supervisor);
  return Number(result.lastInsertRowid);
}

export function updateBooking(
  id: number,
  member_id: number,
  lane_id: number,
  start_time: string,
  end_time: string,
  is_supervisor: boolean
): void {
  const stmt = db.prepare(
    "UPDATE bookings SET member_id = ?, lane_id = ?, start_time = ?, end_time = ?, is_supervisor = ? WHERE id = ?"
  );
  stmt.run(member_id, lane_id, start_time, end_time, is_supervisor, id);
}

export function deleteBooking(id: number): void {
  const stmt = db.prepare("DELETE FROM bookings WHERE id = ?");
  stmt.run(id);
}

