  "code": "import { Router, type Request, type Response } from "express";
import {
  db,
  deleteBooking,
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  try {
    const bookings = getAllBookings();
    res.json(bookings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    res.json(booking);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch booking" });
  }
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  try {
    const { member_id, lane_id, start_time, end_time, is_supervisor } = req.body;

    if (
      member_id === undefined ||
      lane_id === undefined ||
      start_time === undefined ||
      end_time === undefined ||
      is_supervisor === undefined
    ) {
      return res.status(400).json({
        error: "Missing required fields: member_id, lane_id, start_time, end_time, is_supervisor"
      });
    }

    const newId = insertBooking(
      member_id,
      lane_id,
      start_time,
      end_time,
      is_supervisor
    );

    const newBooking = getBookingById(newId);
    if (!newBooking) {
      return res.status(500).json({ error: "Failed to retrieve created booking" });
    }

    res.status(201).json(newBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const { member_id, lane_id, start_time, end_time, is_supervisor } = req.body;

    if (
      member_id === undefined ||
      lane_id === undefined ||
      start_time === undefined ||
      end_time === undefined ||
      is_supervisor === undefined
    ) {
      return res.status(400).json({
        error: "Missing required fields: member_id, lane_id, start_time, end_time, is_supervisor"
      });
    }

    const existingBooking = getBookingById(id);
    if (!existingBooking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    updateBooking(
      id,
      member_id,
      lane_id,
      start_time,
      end_time,
      is_supervisor
    );

    const updatedBooking = getBookingById(id);
    if (!updatedBooking) {
      return res.status(500).json({ error: "Failed to retrieve updated booking" });
    }

    res.json(updatedBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to update booking" });
  }
});

// Delete a booking (supervisor-only)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    // Enforce supervisor-only deletion
    if (!booking.is_supervisor) {
      return res.status(403).json({ error: "Only supervisors can delete bookings" });
    }

    deleteBooking(id);
    res.json({ message: "Booking deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete booking" });
  }
});"
}

