  "code": "import { useEffect, useState } from "react";

interface Plot {
  id: number;
  name: string;
  size: string;
  location: string;
}

interface Reservation {
  id: number;
  plotId: number;
  memberId: number;
  startDate: string;
  endDate: string;
}

export function PlotReservationView() {
  const [plots, setPlots] = useState<Plot[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedPlotId, setSelectedPlotId] = useState<number | null>(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [plotsResponse, reservationsResponse] = await Promise.all([
          fetch("/api/reservations-api/"),
          fetch("/api/reservations-api/"),
        ]);

        if (!plotsResponse.ok || !reservationsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const plotsData = await plotsResponse.json();
        const reservationsData = await reservationsResponse.json();

        setPlots(plotsData);
        setReservations(reservationsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleReserve = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedPlotId || !startDate || !endDate) return;

    try {
      const response = await fetch("/api/reservations-api/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          plotId: selectedPlotId,
          memberId: 1, // Assuming current member ID is 1
          startDate,
          endDate,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to reserve plot");
      }

      // Refresh data after successful reservation
      const [plotsResponse, reservationsResponse] = await Promise.all([
        fetch("/api/reservations-api/"),
        fetch("/api/reservations-api/"),
      ]);

      if (!plotsResponse.ok || !reservationsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const plotsData = await plotsResponse.json();
      const reservationsData = await reservationsResponse.json();

      setPlots(plotsData);
      setReservations(reservationsData);

      // Reset form
      setSelectedPlotId(null);
      setStartDate("");
      setEndDate("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const availablePlots = plots.filter(plot => 
    !reservations.some(res => res.plotId === plot.id)
  );

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h1 style={{ textAlign: "center" }}>Plot Reservation</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Available Plots</h2>
        {availablePlots.length === 0 ? (
          <p>No plots available for reservation.</p>
        ) : (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
            {availablePlots.map(plot => (
              <div 
                key={plot.id} 
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "15px",
                  width: "200px",
                  boxSizing: "border-box",
                }}
              >
                <h3>{plot.name}</h3>
                <p>Size: {plot.size}</p>
                <p>Location: {plot.location}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "20px" }}>
        <h2>Reserve a Plot</h2>
        <form onSubmit={handleReserve}>
          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="plotSelect">Select Plot:</label>
            <select
              id="plotSelect"
              value={selectedPlotId ?? ""}
              onChange={(e) => setSelectedPlotId(Number(e.target.value))}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            >
              <option value="">Choose a plot</option>
              {availablePlots.map(plot => (
                <option key={plot.id} value={plot.id}>{plot.name}</option>
              ))}
            </select>
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="startDate">Start Date:</label>
            <input
              type="date"
              id="startDate"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="endDate">End Date:</label>
            <input
              type="date"
              id="endDate"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>

          <button 
            type="submit" 
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              borderRadius: "4px",
              padding: "10px 20px",
              cursor: "pointer",
            }}
          >
            Reserve Plot
          </button>
        </form>
      </div>
    </div>
  );
}"
}

