interface Reservation {
  id: string;
  startTime: string;
  endTime: string;
}

export function ReservationWidget() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedTimeSlot, setSelectedTimeSlot] = useState<string | null>(null);

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/reservations-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleReserve = async () => {
    if (!selectedTimeSlot) return;

    try {
      const response = await fetch("/api/reservations-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          startTime: selectedTimeSlot,
          endTime: new Date(new Date(selectedTimeSlot).getTime() + 60 * 60 * 1000).toISOString(),
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to reserve spot: ${response.status}`);
      }

      setSelectedTimeSlot(null);
      fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const timeSlots = [
    "2023-05-15T09:00:00Z",
    "2023-05-15T10:00:00Z",
    "2023-05-15T11:00:00Z",
    "2023-05-15T12:00:00Z",
    "2023-05-15T13:00:00Z",
    "2023-05-15T14:00:00Z",
    "2023-05-15T15:00:00Z",
    "2023-05-15T16:00:00Z",
    "2023-05-15T17:00:00Z",
  ];

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Reserve Your Parking Spot</h1>

      <div style={{ marginBottom: "20px" }}>
        <h2>Available Time Slots</h2>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "10px",
          }}
        >
          {timeSlots.map((slot) => {
            const date = new Date(slot);
            const formattedTime = date.toLocaleTimeString([], {
              hour: "2-digit",
              minute: "2-digit",
            });
            const isSelected = selectedTimeSlot === slot;

            return (
              <button
                key={slot}
                onClick={() => setSelectedTimeSlot(slot)}
                style={{
                  padding: "10px 15px",
                  border: "1px solid #ccc",
                  borderRadius: "5px",
                  backgroundColor: isSelected ? "#007bff" : "white",
                  color: isSelected ? "white" : "black",
                  cursor: "pointer",
                  flex: "1 1 calc(50% - 10px)",
                }}
              >
                {formattedTime}
              </button>
            );
          })}
        </div>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Your Reservations</h2>
        {reservations.length === 0 ? (
          <p>No reservations found.</p>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Start Time</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>End Time</th>
              </tr>
            </thead>
            <tbody>
              {reservations.map((reservation) => {
                const start = new Date(reservation.startTime);
                const end = new Date(reservation.endTime);
