      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      const response = await fetch('/api/reservations-api/exports', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      });

      if (!response.ok) {
        throw new Error(`Failed to export reservations: ${response.status} ${response.statusText}`);
      }

      const exportData = await response.json();
      const exportId = exportData.id;

      // Poll for export completion
      let exportResult;
      while (!exportResult || exportResult.status === 'processing') {
        const resultResponse = await fetch(`/api/reservations-api/exports/${exportId}`);
        if (!resultResponse.ok) {
          throw new Error(`Failed to get export result: ${resultResponse.status} ${resultResponse.statusText}`);
