export const db = new DatabaseSync("./club-budget.db");

interface Expense {
  id: number;
  memberId: number;
  amount: number;
  category: string;
  date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS expenses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    memberId INTEGER NOT NULL,
    amount REAL NOT NULL,
    category TEXT NOT NULL,
    date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllExpenses(): Expense[] {
  const stmt = db.prepare("SELECT * FROM expenses");
  return stmt.all() as unknown as Expense[];
}

export function getExpenseById(id: number): Expense | undefined {
  const stmt = db.prepare("SELECT * FROM expenses WHERE id = ?");
  return stmt.get(id) as unknown as Expense | undefined;
}

export function insertExpense(expense: Omit<Expense, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO expenses (memberId, amount, category, date) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(expense.memberId, expense.amount, expense.category, expense.date);
  return Number(result.lastInsertRowid);
}

export function updateExpense(id: number, expense: Partial<Omit<Expense, "id">>): boolean {
  const fields = [];
  const values = [];

  if (expense.memberId !== undefined) {
    fields.push("memberId = ?");
    values.push(expense.memberId);
  }

  if (expense.amount !== undefined) {
    fields.push("amount = ?");
    values.push(expense.amount);
  }

  if (expense.category !== undefined) {
    fields.push("category = ?");
    values.push(expense.category);
  }

  if (expense.date !== undefined) {
    fields.push("date = ?");
    values.push(expense.date);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE expenses SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteExpense(id: number): boolean {
  const stmt = db.prepare("DELETE FROM expenses WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

