interface Transaction {
  id: string;
  description: string;
  amount: number;
  date: string;
}

export function OwnerOnlyExportButton() {
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [hasPermission, setHasPermission] = useState<boolean | null>(null);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchExportGuard = async () => {
      try {
        const response = await fetch("/api/export-guard/history");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setHasPermission(data.canExport);
      } catch (err) {
        setError("Failed to check export permission.");
        setHasPermission(false);
      } finally {
        setIsLoading(false);
      }
    };

    const fetchTransactions = async () => {
      try {
        const response = await fetch("/api/expenses-api/");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setTransactions(data);
      } catch (err) {
        setError("Failed to fetch transactions.");
      }
    };

    fetchExportGuard();
    fetchTransactions();
  }, []);

  const handleExport = async () => {
    try {
      const response = await fetch("/api/expenses-api/export", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ transactions }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "club-expenses-export.csv";
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError("Failed to export transactions.");
    }
  };

  if (isLoading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (hasPermission === false) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Access denied.</div>;
  }

  if (hasPermission === null) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Checking permissions...</div>;
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px" }}>
      <button 
        onClick={handleExport}
        style={{
          backgroundColor: "#4CAF50",
          border: "none",
          color: "white",
          padding: "10px 20px",
          textAlign: "center",
          textDecoration: "none",
          display: "inline-block",
          fontSize: "16px",
          margin: "4px 2px",
          cursor: "pointer",
          borderRadius: "4px",
        }}
      >
        Export All Transactions
      </button>
    </div>
  );
}"
}

