export const db = new DatabaseSync(
  "./backend/src/db/community-solar-co-op.db"
);

interface UsageEvent {
  id: number;
  memberId: number;
  kwhUsed: number;
  date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS usage_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    memberId INTEGER NOT NULL,
    kwhUsed REAL NOT NULL,
    date TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllUsageEvents(): UsageEvent[] {
  const stmt = db.prepare(`
    SELECT * FROM usage_events
  `);
  return stmt.all() as unknown as UsageEvent[];
}

export function getUsageEventById(id: number): UsageEvent | undefined {
  const stmt = db.prepare(`
    SELECT * FROM usage_events WHERE id = ?
  `);
  return stmt.get(id) as unknown as UsageEvent | undefined;
}

export function insertUsageEvent(
  memberId: number,
  kwhUsed: number,
  date: string
): number {
  const stmt = db.prepare(`
    INSERT INTO usage_events (memberId, kwhUsed, date)
    VALUES (?, ?, ?)
  `);
  const result = stmt.run(memberId, kwhUsed, date);
  return Number(result.lastInsertRowid);
}

export function updateUsageEvent(
  id: number,
  memberId: number,
  kwhUsed: number,
  date: string
): void {
  const stmt = db.prepare(`
    UPDATE usage_events
    SET memberId = ?, kwhUsed = ?, date = ?
    WHERE id = ?
  `);
  stmt.run(memberId, kwhUsed, date, id);
}

export function deleteUsageEvent(id: number): void {
  const stmt = db.prepare(`
    DELETE FROM usage_events WHERE id = ?
  `);
  stmt.run(id);
}

