export const db = new DatabaseSync("./routes.db");

interface Route {
  id: number;
  name: string;
  wall_id: number;
  setter_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS routes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    wall_id INTEGER NOT NULL,
    setter_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRoutes(): Route[] {
  const stmt = db.prepare("SELECT * FROM routes");
  return stmt.all() as unknown as Route[];
}

export function getRouteById(id: number): Route | undefined {
  const stmt = db.prepare("SELECT * FROM routes WHERE id = ?");
  return stmt.get(id) as unknown as Route | undefined;
}

export function insertRoute(name: string, wallId: number, setterId: number): number {
  const stmt = db.prepare(
    "INSERT INTO routes (name, wall_id, setter_id) VALUES (?, ?, ?)"
  );
  const result = stmt.run(name, wallId, setterId);
  return Number(result.lastInsertRowid);
}

export function updateRoute(id: number, name: string, wallId: number, setterId: number): void {
  const stmt = db.prepare(
    "UPDATE routes SET name = ?, wall_id = ?, setter_id = ? WHERE id = ?"
  );
  stmt.run(name, wallId, setterId, id);
}

export function deleteRoute(id: number): void {
  const stmt = db.prepare("DELETE FROM routes WHERE id = ?");
  stmt.run(id);
}

