  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Component mounts, but we don't need to fetch data for export
    // The export functionality is triggered by a button click
    setLoading(false);
  }, []);

  const handleExportClick = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch('/api/export-service/export', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Export failed: ${response.status} ${response.statusText}`);
      }

      // Get the CSV content from the response
      const csvContent = await response.text();

      // Create a blob and download it
      const blob = new Blob([csvContent], { type: 'text/csv' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'bookings_export.csv';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
