  "code": "import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as workoutsRouter } from "../routes/workouts-api";
import { router as authServiceRouter } from "../routes/auth-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect requests to workouts API routes
  if (!req.path.startsWith("/api/workouts")) {
    next();
    return;
  }

  // Check if the request is for reading workout logs (GET requests)
  if (req.method !== "GET") {
    next();
    return;
  }

  // Extract user ID from token (simplified for this example)
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    // This is a simplified version - in practice, you'd decode the JWT and verify its signature
    const [userId, tokenSecret] = token.split(":");

    if (!userId || !tokenSecret) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Create expected HMAC
    const expectedHmac = createHmac("sha256", secret)
      .update(userId)
      .digest();

    // Compare with provided token
    const providedHmac = Buffer.from(tokenSecret, "hex");

    if (expectedHmac.length !== providedHmac.length) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(expectedHmac, providedHmac);

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // Check if the requested workout log belongs to the authenticated user
    const requestedUserId = req.params.userId;
    if (requestedUserId && requestedUserId !== userId) {
      res.status(403).json({ error: "Forbidden: Cannot access another user's workout log" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}"
}

