export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply privacy guard to GET requests to check-in routes
  if (req.method !== "GET" || !req.path.startsWith("/check-ins")) {
    next();
    return;
  }

  // For GET requests to check-in routes, check if member is trying to access
  // another member's data
  const memberId = req.params.memberId;
  const authenticatedMemberId = req.headers["x-member-id"] as string | undefined;

  // If no authenticated member ID, allow access (let other middleware handle auth)
  if (!authenticatedMemberId) {
    next();
    return;
  }

  // If the requested member ID doesn't match the authenticated member ID,
  // reject the request
  if (memberId && memberId !== authenticatedMemberId) {
    res.status(403).json({ error: "Access denied" });
    return;
  }

  next();
}"
}

