{
  "code": "import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check access for PATCH requests to /repair-logs/
  if (req.method !== "PATCH" || !req.path.startsWith("/repair-logs/")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  // For this exercise, we'll assume the token contains role info
  try {
    const [payload] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest();

    const actualSignature = createHmac("sha256", secret)
      .update(payload)
      .digest();

    const isValid = timingSafeEqual(expectedSignature, actualSignature);

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // In a real implementation, we would decode the token to get user role
    // For now, we'll just check if it's a member trying to access another member's log
    const userId = req.params.userId;
    const requestingUserId = req.user?.id; // Assuming user is attached to request

    if (requestingUserId && userId && requestingUserId !== userId) {
      res.status(403).json({ error: "Forbidden: Access denied" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token format" });
  }
}"
}

