export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to shifts API routes
  if (!req.path.startsWith("/api/shifts")) {
    next();
    return;
  }

  // For GET requests to shifts API, check if user can access the requested member
  if (req.method === "GET" && req.path.includes("/members/")) {
    // Extract member ID from path
    const pathParts = req.path.split("/");
    const memberIdIndex = pathParts.indexOf("members") + 1;

    if (memberIdIndex > 0 && memberIdIndex < pathParts.length) {
      const requestedMemberId = pathParts[memberIdIndex];

      // Check if user is trying to access their own shifts
      if (req.user && req.user.id !== requestedMemberId) {
        res.status(403).json({ error: "Forbidden: Cannot access another member's shifts" });
        return;
      }
    }
  }

  next();
}"
}

