    "code": "import { Router, type Request, type Response } from "express";
import { 
  getAllSessions,
  getSessionById,
  insertSession,
  updateSession,
  deleteSession
} from "../db/sessions-table";

export const router = Router();

// GET /sessions - Get all sessions
router.get("/sessions", (req: Request, res: Response) => {
  try {
    const sessions = getAllSessions();
    res.json(sessions);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch sessions" });
  }
});

// GET /sessions/:id - Get a session by ID
router.get("/sessions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid session ID" });
    }

    const session = getSessionById(id);
    if (!session) {
      return res.status(404).json({ error: "Session not found" });
    }

    res.json(session);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch session" });
  }
});

// POST /sessions - Create a new session
router.post("/sessions", (req: Request, res: Response) => {
  try {
    const { tutorId, studentId, completed } = req.body;

    if (typeof tutorId !== "number" || typeof studentId !== "number" || typeof completed !== "boolean") {
      return res.status(400).json({ error: "Invalid session data" });
    }

    const sessionId = insertSession(tutorId, studentId, completed);
    const newSession = getSessionById(sessionId);

    if (!newSession) {
      return res.status(500).json({ error: "Failed to create session" });
    }

    res.status(201).json(newSession);
  } catch (error) {
    res.status(500).json({ error: "Failed to create session" });
  }
});

// PUT /sessions/:id - Update a session
router.put("/sessions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid session ID" });
    }

    const { tutorId, studentId, completed } = req.body;

    if (typeof tutorId !== "number" || typeof studentId !== "number" || typeof completed !== "boolean") {
      return res.status(400).json({ error: "Invalid session data" });
    }

    const existingSession = getSessionById(id);
    if (!existingSession) {
      return res.status(404).json({ error: "Session not found" });
    }

    updateSession(id, tutorId, studentId, completed);
    const updatedSession = getSessionById(id);

    if (!updatedSession) {
      return res.status(500).json({ error: "Failed to update session" });
    }

    res.json(updatedSession);
  } catch (error) {
    res.status(500).json({ error: "Failed to update session" });
  }
});

// DELETE /sessions/:id - Delete a session
router.delete("/sessions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid session ID" });
    }

    const existingSession = getSessionById(id);
    if (!existingSession) {
      return res.status(404).json({ error: "Session not found" });
    }

    deleteSession(id);
    res.json({ message: "Session deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete session" });
  }
});"
