  "code": "import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check requests that involve session data access
  const sessionPaths = [/^\/api\/sessions\/[^\/]+$/, /^\/api\/sessions$/];

  const isSessionRequest = sessionPaths.some(path => path.test(req.path));

  if (!isSessionRequest) {
    next();
    return;
  }

  // Check if user is a regular member
  const userRole = req.headers["x-user-role"];
  const userId = req.headers["x-user-id"];

  if (userRole !== "regular-member") {
    next();
    return;
  }

  // For GET requests to specific session endpoints
  if (req.method === "GET" && req.path.match(/^\/api\/sessions\/[^\/]+$/)) {
    const requestedUserId = req.path.split('/')[5];

    if (requestedUserId && requestedUserId !== userId) {
      res.status(403).json({ error: "Forbidden: Regular members can only view their own sessions." });
      return;
    }
  }

  // For GET requests to sessions list endpoint
  if (req.method === "GET" && req.path === "/api/sessions") {
    const queryUserId = req.query.userId as string;

    if (queryUserId && queryUserId !== userId) {
      res.status(403).json({ error: "Forbidden: Regular members can only view their own sessions." });
      return;
    }
  }

  // Allow access for authorized requests
  next();
}"
}

