} from "../db/categories-table";

export const router = Router();

// GET /submissions - Get all submissions
router.get("/submissions", (req: Request, res: Response) => {
  try {
    const submissions = getAllSubmissions();
    return res.json(submissions);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch submissions" });
  }
});

// GET /submissions/:id - Get a submission by ID
router.get("/submissions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid submission ID" });
    }

    const submission = getSubmissionById(id);
    if (!submission) {
      return res.status(404).json({ error: "Submission not found" });
    }

    return res.json(submission);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch submission" });
  }
});

// POST /submissions - Create a new submission
router.post("/submissions", (req: Request, res: Response) => {
  try {
    const { manuscriptText, categoryId, authorId } = req.body;

    if (!manuscriptText || !categoryId || !authorId) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const category = getCategoryById(categoryId);
    if (!category) {
      return res.status(400).json({ error: "Invalid category ID" });
    }

    const userRole = getUserRoleById(authorId);
    if (!userRole) {
      // If user doesn't have a role, assign 'author' role
      insertUserRole(authorId, "author");
    } else if (userRole.role !== "author") {
      // If user has a different role, update to 'author'
      updateUserRole(authorId, "author");
    }

    const newId = insertSubmission(manuscriptText, categoryId, authorId);
    const newSubmission = getSubmissionById(newId);

    if (!newSubmission) {
      return res.status(500).json({ error: "Failed to create submission" });
    }

    return res.status(201).json(newSubmission);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create submission" });
  }
});

// PUT /submissions/:id - Update a submission
router.put("/submissions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid submission ID" });
    }

    const { manuscriptText, categoryId, authorId } = req.body;

    if (!manuscriptText || !categoryId || !authorId) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingSubmission = getSubmissionById(id);
    if (!existingSubmission) {
      return res.status(404).json({ error: "Submission not found" });
    }

    const category = getCategoryById(categoryId);
    if (!category) {
      return res.status(400).json({ error: "Invalid category ID" });
    }

    const updatedId = updateSubmission(id, manuscriptText, categoryId, authorId);
    const updatedSubmission = getSubmissionById(updatedId);

    if (!updatedSubmission) {
      return res.status(500).json({ error: "Failed to update submission" });
    }

    return res.json(updatedSubmission);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update submission" });
  }
});

// DELETE /submissions/:id - Delete a submission
router.delete("/submissions/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid submission ID" });
    }

    const existingSubmission = getSubmissionById(id);
    if (!existingSubmission) {
      return res.status(404).json({ error: "Submission not found" });
    }

    const deletedId = deleteSubmission(id);
    if (deletedId !== id) {
