export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check read operations on submissions API routes
  if (!(req.method === "GET" && req.path.startsWith("/api/submissions"))) {
    next();
    return;
  }

  // Check if user is a regular member
  const userRole = req.headers["x-user-role"] as string | undefined;
  if (userRole !== "regular-member") {
    next();
    return;
  }

  // For regular members, check if they're trying to access their own submission
  const submissionId = req.params.id;
  const userId = req.headers["x-user-id"] as string | undefined;

